  1→/**
  2→ * OAuth subscription management routes.
  3→ *
  4→ * Handles OAuth flow for subscription-based LLM providers (Anthropic Claude Pro, etc.)
  5→ */
  6→
  7→import { Router } from "express";
  8→import type { Request, Response } from "express";
  9→import { requireAuth } from "../auth/middleware.js";
 10→import { OAuthService } from "../services/oauth-service.js";
 11→import type { CryptoService } from "../services/crypto.js";
 12→import { getDatabase } from "../db/index.js";
 13→import { generatePKCE } from "../utils/pkce.js";
 14→
 15→// OAuth provider configurations
 16→const OAUTH_PROVIDERS = {
 17→	anthropic: {
 18→		clientId: "9d1c250a-e61b-44d9-88ed-5944d1962f5e",
 19→		authorizeUrl: "https://claude.ai/oauth/authorize",
 20→		tokenUrl: "https://console.anthropic.com/v1/oauth/token",
 21→		redirectUri: "https://console.anthropic.com/oauth/code/callback",
 22→		scopes: "org:create_api_key user:profile user:inference",
 23→	},
 24→	"openai-codex": {
 25→		clientId: "chatgpt-oauth-cli",
 26→		authorizeUrl: "https://auth.openai.com/oauth/authorize",
 27→		tokenUrl: "https://auth.openai.com/oauth/token",
 28→		redirectUri: "http://localhost:1455/auth/callback",
 29→		scopes: "openai profile email offline_access",
 30→	},
 31→};
 32→
 33→// Temporary storage for PKCE verifiers (in production, use Redis)
 34→const pkceStorage = new Map<string, { verifier: string; userId: string; expiresAt: number }>();
 35→
 36→// Clean up expired PKCE entries every 10 minutes
 37→setInterval(() => {
 38→	const now = Date.now();
 39→	for (const [key, value] of pkceStorage.entries()) {
 40→		if (value.expiresAt < now) {
 41→			pkceStorage.delete(key);
 42→		}
 43→	}
 44→}, 10 * 60 * 1000);
 45→
 46→export function createOAuthRouter(crypto: CryptoService): Router {
 47→	const router = Router();
 48→	const db = getDatabase();
 49→	// @ts-expect-error Database wrapper is compatible with Pool for OAuthService usage
 50→	const oauthService = new OAuthService(db, crypto);
 51→
 52→	// All routes require authentication
 53→	router.use(requireAuth);
 54→
 55→	// -----------------------------------------------------------------------
 56→	// POST /:provider/start — Start OAuth flow for any provider
 57→	// -----------------------------------------------------------------------
 58→	router.post("/:provider/start", async (req: Request, res: Response) => {
 59→		try {
 60→			const { provider } = req.params;
 61→			const userId = req.user!.userId;
 62→
 63→			// Validate provider
 64→			// @ts-expect-error Express 5 params type is string | string[]
 65→			if (!(provider in OAUTH_PROVIDERS)) {
 66→				res.status(400).json({ success: false, error: "Unsupported provider" });
 67→				return;
 68→			}
 69→
 70→			const config = OAUTH_PROVIDERS[provider as keyof typeof OAUTH_PROVIDERS];
 71→
 72→			// Generate PKCE challenge
 73→			const { verifier, challenge } = await generatePKCE();
 74→
 75→			// Store verifier temporarily (expires in 10 minutes)
 76→			const stateKey = `${provider}-${userId}-${Date.now()}`;
 77→			pkceStorage.set(stateKey, {
 78→				verifier,
 79→				userId,
 80→				expiresAt: Date.now() + 10 * 60 * 1000,
 81→			});
 82→
 83→			// Build authorization URL
 84→			const authParams = new URLSearchParams({
 85→				code: "true",
 86→				client_id: config.clientId,
 87→				response_type: "code",
 88→				redirect_uri: config.redirectUri,
 89→				scope: config.scopes,
 90→				code_challenge: challenge,
 91→				code_challenge_method: "S256",
 92→				state: stateKey,
 93→			});
 94→
 95→			// Provider-specific parameters
 96→			if (provider === "openai-codex") {
 97→				authParams.set("codex_cli_simplified_flow", "true");
 98→				authParams.set("id_token_add_organizations", "true");
 99→				authParams.set("originator", "pi");
100→			}
101→
102→			const authUrl = `${config.authorizeUrl}?${authParams.toString()}`;
103→
104→			res.json({
105→				success: true,
106→				data: {
107→					authUrl,
108→					state: stateKey,
109→				},
110→			});
111→		} catch (err) {
112→			console.error(`[oauth] POST /:provider/start error:`, err);
113→			res.status(500).json({ success: false, error: "Failed to start OAuth flow" });
114→		}
115→	});
116→
117→	// -----------------------------------------------------------------------
118→	// POST /:provider/callback — Handle OAuth callback with authorization code
119→	// -----------------------------------------------------------------------
120→	router.post("/:provider/callback", async (req: Request, res: Response) => {
121→		try {
122→			const { provider } = req.params;
123→			const { code, state } = req.body;
124→			const userId = req.user!.userId;
125→
126→			// Validate provider
127→			// @ts-expect-error Express 5 params type is string | string[]
128→			if (!(provider in OAUTH_PROVIDERS)) {
129→				res.status(400).json({ success: false, error: "Unsupported provider" });
130→				return;
131→			}
132→
133→			if (!code || typeof code !== "string") {
134→				res.status(400).json({ success: false, error: "code is required" });
135→				return;
136→			}
137→			if (!state || typeof state !== "string") {
138→				res.status(400).json({ success: false, error: "state is required" });
139→				return;
140→			}
141→
142→			// Retrieve and validate PKCE verifier
143→			const pkceData = pkceStorage.get(state);
144→			if (!pkceData) {
145→				res.status(400).json({ success: false, error: "Invalid or expired state" });
146→				return;
147→			}
148→			if (pkceData.userId !== userId) {
149→				res.status(403).json({ success: false, error: "State does not match user" });
150→				return;
151→			}
152→
153→			// Clean up PKCE storage
154→			pkceStorage.delete(state);
155→
156→			const config = OAUTH_PROVIDERS[provider as keyof typeof OAUTH_PROVIDERS];
157→
158→			// Exchange code for tokens
159→			const tokenResponse = await fetch(config.tokenUrl, {
160→				method: "POST",
161→				headers: {
162→					"Content-Type": "application/json",
163→				},
164→				body: JSON.stringify({
165→					grant_type: "authorization_code",
166→					client_id: config.clientId,
167→					code: code,
168→					state: state,
169→					redirect_uri: config.redirectUri,
170→					code_verifier: pkceData.verifier,
171→				}),
172→			});
173→
174→			if (!tokenResponse.ok) {
175→				const error = await tokenResponse.text();
176→				console.error(`[oauth] Token exchange failed for ${provider}:`, error);
177→				res.status(400).json({ success: false, error: "Token exchange failed" });
178→				return;
179→			}
180→
181→			const tokenData = (await tokenResponse.json()) as {
182→				access_token: string;
183→				refresh_token: string;
184→				expires_in: number;
185→			};
186→
187→			// Calculate expiry time (current time + expires_in seconds - 5 min buffer)
188→			const expiresAt = Date.now() + tokenData.expires_in * 1000 - 5 * 60 * 1000;
189→
190→			// Store credentials
191→			await oauthService.storeCredentials(
192→				provider as any,
193→				{
194→					refresh: tokenData.refresh_token,
195→					access: tokenData.access_token,
196→					expires: expiresAt,
197→				},
198→				{ userId },
199→			);
200→
201→			res.json({
202→				success: true,
203→				data: {
204→					provider,
205→					expiresAt: new Date(expiresAt).toISOString(),
206→				},
207→			});
208→		} catch (err) {
209→			console.error(`[oauth] POST /:provider/callback error:`, err);
210→			res.status(500).json({ success: false, error: "Failed to complete OAuth flow" });
211→		}
212→	});
213→
214→	// -----------------------------------------------------------------------
215→	// GET /:provider/status — Check if user has OAuth credentials for provider
216→	// -----------------------------------------------------------------------
217→	router.get("/:provider/status", async (req: Request, res: Response) => {
218→		try {
219→			const { provider } = req.params;
220→			const userId = req.user!.userId;
221→
222→			const credentials = await oauthService.getCredentials(provider as any, { userId });
223→
224→			if (!credentials) {
225→				res.json({
226→					success: true,
227→					data: {
228→						connected: false,
229→					},
230→				});
231→				return;
232→			}
233→
234→			res.json({
235→				success: true,
236→				data: {
237→					connected: true,
238→					expiresAt: new Date(credentials.expires).toISOString(),
239→					expired: credentials.expires < Date.now(),
240→				},
241→			});
242→		} catch (err) {
243→			console.error(`[oauth] GET /:provider/status error:`, err);
244→			res.status(500).json({ success: false, error: "Failed to check OAuth status" });
245→		}
246→	});
247→
248→	// -----------------------------------------------------------------------
249→	// DELETE /:provider — Disconnect OAuth for provider
250→	// -----------------------------------------------------------------------
251→	router.delete("/:provider", async (req: Request, res: Response) => {
252→		try {
253→			const { provider } = req.params;
254→			const userId = req.user!.userId;
255→
256→			const deleted = await oauthService.deleteCredentials(provider as any, { userId });
257→
258→			if (!deleted) {
259→				res.status(404).json({ success: false, error: "No OAuth credentials found" });
260→				return;
261→			}
262→
263→			res.json({ success: true });
264→		} catch (err) {
265→			console.error(`[oauth] DELETE /:provider error:`, err);
266→			res.status(500).json({ success: false, error: "Failed to disconnect OAuth" });
267→		}
268→	});
269→
270→	// -----------------------------------------------------------------------
271→	// GET / — List all OAuth connections for user
272→	// -----------------------------------------------------------------------
273→	router.get("/", async (req: Request, res: Response) => {
274→		try {
275→			const userId = req.user!.userId;
276→
277→			const credentials = await oauthService.listCredentials({ userId });
278→
279→			res.json({
280→				success: true,
281→				data: {
282→					credentials: credentials.map((cred) => ({
283→						provider: cred.provider,
284→						expiresAt: cred.expiresAt.toISOString(),
285→						expired: cred.expiresAt.getTime() < Date.now(),
286→						createdAt: cred.createdAt.toISOString(),
287→						updatedAt: cred.updatedAt.toISOString(),
288→					})),
289→				},
290→			});
291→		} catch (err) {
292→			console.error("[oauth] GET / error:", err);
293→			res.status(500).json({ success: false, error: "Failed to list OAuth credentials" });
294→		}
295→	});
296→
297→	return router;
298→}
299→

  1→/**
  2→ * OAuth credential management service.
  3→ *
  4→ * Handles storage, retrieval, and automatic refresh of OAuth credentials
  5→ * for subscription-based LLM providers (Anthropic Claude Pro, OpenAI Codex, etc.)
  6→ */
  7→
  8→import type { Pool } from "pg";
  9→import type { CryptoService } from "./crypto.js";
 10→import { getOAuthApiKey } from "@mariozechner/pi-ai/oauth";
 11→
 12→export interface OAuthCredentials {
 13→	refresh: string;
 14→	access: string;
 15→	expires: number; // Expiration timestamp in milliseconds
 16→	[key: string]: unknown;
 17→}
 18→
 19→export interface StoredOAuthCredential {
 20→	id: string;
 21→	userId?: string;
 22→	teamId?: string;
 23→	provider: string;
 24→	expiresAt: Date;
 25→	createdAt: Date;
 26→	updatedAt: Date;
 27→}
 28→
 29→interface OAuthCredentialRow {
 30→	id: string;
 31→	user_id?: string;
 32→	team_id?: string;
 33→	provider: string;
 34→	encrypted_dek: Buffer;
 35→	encrypted_refresh: Buffer;
 36→	encrypted_access: Buffer;
 37→	iv: Buffer;
 38→	expires_at: Date;
 39→	key_version: number;
 40→	created_at: Date;
 41→	updated_at: Date;
 42→}
 43→
 44→export type OAuthProviderId =
 45→	| "anthropic"
 46→	| "openai-codex"
 47→	| "github-copilot"
 48→	| "google-gemini-cli"
 49→	| "google-antigravity";
 50→
 51→export class OAuthService {
 52→	constructor(
 53→		private db: Pool,
 54→		private crypto: CryptoService,
 55→	) {}
 56→
 57→	/**
 58→	 * Store OAuth credentials for a user or team.
 59→	 * Credentials are encrypted using envelope encryption.
 60→	 */
 61→	async storeCredentials(
 62→		provider: OAuthProviderId,
 63→		credentials: OAuthCredentials,
 64→		options: { userId?: string; teamId?: string },
 65→	): Promise<void> {
 66→		if (!options.userId && !options.teamId) {
 67→			throw new Error("Either userId or teamId must be provided");
 68→		}
 69→		if (options.userId && options.teamId) {
 70→			throw new Error("Cannot specify both userId and teamId");
 71→		}
 72→
 73→		// Encrypt both tokens as a single blob so they share the same DEK/IV.
 74→		// The encrypted_refresh column stores the combined blob; encrypted_access
 75→		// is set to an empty buffer (kept for schema compatibility).
 76→		const combined = JSON.stringify({ refresh: credentials.refresh, access: credentials.access });
 77→		const envelope = this.crypto.encrypt(combined);
 78→
 79→		const expiresAt = new Date(credentials.expires);
 80→
 81→		const conflictColumn = options.userId ? "user_id" : "team_id";
 82→		const result = await this.db.query(
 83→			`INSERT INTO oauth_credentials
 84→			 (user_id, team_id, provider, encrypted_dek, encrypted_refresh, encrypted_access, iv, expires_at, key_version)
 85→			 VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
 86→			 ON CONFLICT (${conflictColumn}, provider)
 87→			 DO UPDATE SET
 88→			   encrypted_dek = $4,
 89→			   encrypted_refresh = $5,
 90→			   encrypted_access = $6,
 91→			   iv = $7,
 92→			   expires_at = $8,
 93→			   key_version = $9,
 94→			   updated_at = now()
 95→			 RETURNING id`,
 96→			[
 97→				options.userId || null,
 98→				options.teamId || null,
 99→				provider,
100→				envelope.encryptedDek,
101→				envelope.encryptedData,
102→				Buffer.alloc(0),
103→				envelope.iv,
104→				expiresAt,
105→				envelope.keyVersion,
106→			],
107→		);
108→
109→		// Audit log
110→		await this.db.query(
111→			`INSERT INTO oauth_audit_log (user_id, team_id, provider, action)
112→			 VALUES ($1, $2, $3, $4)`,
113→			[options.userId || null, options.teamId || null, provider, "store"],
114→		);
115→
116→		console.log(`[oauth-service] Stored credentials for provider=${provider}, id=${result.rows[0].id}`);
117→	}
118→
119→	/**
120→	 * Retrieve OAuth credentials for a user or team.
121→	 * Returns null if no credentials found.
122→	 */
123→	async getCredentials(
124→		provider: OAuthProviderId,
125→		options: { userId?: string; teamId?: string },
126→	): Promise<OAuthCredentials | null> {
127→		if (!options.userId && !options.teamId) {
128→			throw new Error("Either userId or teamId must be provided");
129→		}
130→
131→		const result = await this.db.query<OAuthCredentialRow>(
132→			`SELECT * FROM oauth_credentials
133→			 WHERE provider = $1
134→			   AND (user_id = $2 OR team_id = $3)
135→			 LIMIT 1`,
136→			[provider, options.userId || null, options.teamId || null],
137→		);
138→
139→		if (result.rows.length === 0) {
140→			return null;
141→		}
142→
143→		const row = result.rows[0];
144→
145→		// Decrypt combined token blob (stored in encrypted_refresh column)
146→		const combined = this.crypto.decrypt({
147→			encryptedDek: row.encrypted_dek,
148→			encryptedData: row.encrypted_refresh,
149→			iv: row.iv,
150→			keyVersion: row.key_version,
151→		});
152→
153→		const { refresh, access } = JSON.parse(combined) as { refresh: string; access: string };
154→
155→		return {
156→			refresh,
157→			access,
158→			expires: row.expires_at.getTime(),
159→		};
160→	}
161→
162→	/**
163→	 * Get an API key from OAuth credentials, automatically refreshing if needed.
164→	 * Returns null if no credentials found.
165→	 */
166→	async getApiKey(
167→		provider: OAuthProviderId,
168→		options: { userId?: string; teamId?: string },
169→	): Promise<string | null> {
170→		const credentials = await this.getCredentials(provider, options);
171→		if (!credentials) {
172→			return null;
173→		}
174→
175→		// Use pi-ai's built-in refresh logic (expects a Record keyed by provider ID)
176→		const result = await getOAuthApiKey(provider, { [provider]: credentials });
177→		if (!result) {
178→			return null;
179→		}
180→
181→		// If credentials were refreshed, store the new ones
182→		if (result.newCredentials) {
183→			await this.storeCredentials(provider, result.newCredentials, options);
184→		}
185→
186→		return result.apiKey;
187→	}
188→
189→	/**
190→	 * Delete OAuth credentials for a user or team.
191→	 */
192→	async deleteCredentials(
193→		provider: OAuthProviderId,
194→		options: { userId?: string; teamId?: string },
195→	): Promise<boolean> {
196→		if (!options.userId && !options.teamId) {
197→			throw new Error("Either userId or teamId must be provided");
198→		}
199→
200→		const result = await this.db.query(
201→			`DELETE FROM oauth_credentials
202→			 WHERE provider = $1
203→			   AND (user_id = $2 OR team_id = $3)`,
204→			[provider, options.userId || null, options.teamId || null],
205→		);
206→
207→		if (result.rowCount && result.rowCount > 0) {
208→			// Audit log
209→			await this.db.query(
210→				`INSERT INTO oauth_audit_log (user_id, team_id, provider, action)
211→				 VALUES ($1, $2, $3, $4)`,
212→				[options.userId || null, options.teamId || null, provider, "delete"],
213→			);
214→			return true;
215→		}
216→
217→		return false;
218→	}
219→
220→	/**
221→	 * List all OAuth credentials for a user or team.
222→	 * Returns only metadata, not the actual credentials.
223→	 */
224→	async listCredentials(options: {
225→		userId?: string;
226→		teamId?: string;
227→	}): Promise<StoredOAuthCredential[]> {
228→		if (!options.userId && !options.teamId) {
229→			throw new Error("Either userId or teamId must be provided");
230→		}
231→
232→		const result = await this.db.query<OAuthCredentialRow>(
233→			`SELECT id, user_id, team_id, provider, expires_at, created_at, updated_at
234→			 FROM oauth_credentials
235→			 WHERE user_id = $1 OR team_id = $2
236→			 ORDER BY provider`,
237→			[options.userId || null, options.teamId || null],
238→		);
239→
240→		return result.rows.map((row) => ({
241→			id: row.id,
242→			userId: row.user_id,
243→			teamId: row.team_id,
244→			provider: row.provider,
245→			expiresAt: row.expires_at,
246→			createdAt: row.created_at,
247→			updatedAt: row.updated_at,
248→		}));
249→	}
250→}
251→

  1→/**
  2→ * OAuth Connections Panel.
  3→ *
  4→ * User-level component for connecting subscription-based LLM providers
  5→ * (Anthropic Claude Pro, OpenAI Codex, GitHub Copilot, etc.)
  6→ */
  7→
  8→import { apiFetch } from "../shared/api.js";
  9→import { LitElement, html, css } from "lit";
 10→import { customElement, property, state } from "lit/decorators.js";
 11→
 12→interface OAuthConnectionInfo {
 13→	provider: string;
 14→	expiresAt: string;
 15→	expired: boolean;
 16→	createdAt: string;
 17→	updatedAt: string;
 18→}
 19→
 20→const PROVIDER_LABELS: Record<string, string> = {
 21→	anthropic: "Anthropic (Claude Pro/Max)",
 22→	"openai-codex": "OpenAI Codex (ChatGPT Plus/Pro)",
 23→	"github-copilot": "GitHub Copilot",
 24→	"google-gemini-cli": "Google Gemini CLI",
 25→	"google-antigravity": "Google Antigravity",
 26→};
 27→
 28→const PROVIDER_DESCRIPTIONS: Record<string, string> = {
 29→	anthropic: "Connect your Claude Pro or Claude Max subscription",
 30→	"openai-codex": "Connect your ChatGPT Plus or Pro subscription",
 31→	"github-copilot": "Connect your GitHub Copilot subscription (device code flow)",
 32→	"google-gemini-cli": "Connect your Google Gemini CLI account (Google OAuth)",
 33→	"google-antigravity": "Connect your Google Antigravity account (Google OAuth)",
 34→};
 35→
 36→// Providers that are fully supported
 37→const SUPPORTED_PROVIDERS = new Set(["anthropic", "openai-codex"]);
 38→
 39→// Providers that need additional implementation (device code flow, etc.)
 40→const COMING_SOON_PROVIDERS = new Set(["github-copilot", "google-gemini-cli", "google-antigravity"]);
 41→
 42→@customElement("oauth-connections-panel")
 43→export class OAuthConnectionsPanel extends LitElement {
 44→	static override styles = css`
 45→		:host {
 46→			display: block;
 47→			padding: 1rem;
 48→		}
 49→		.connection-list {
 50→			display: flex;
 51→			flex-direction: column;
 52→			gap: 0.5rem;
 53→			margin-bottom: 1rem;
 54→		}
 55→		.connection-item {
 56→			display: flex;
 57→			align-items: center;
 58→			justify-content: space-between;
 59→			padding: 0.75rem 1rem;
 60→			border: 1px solid var(--border, #e5e7eb);
 61→			border-radius: 0.5rem;
 62→			background: var(--card, #fff);
 63→		}
 64→		.connection-item.expired {
 65→			border-color: var(--destructive, #dc2626);
 66→			opacity: 0.7;
 67→		}
 68→		.connection-info {
 69→			display: flex;
 70→			flex-direction: column;
 71→			gap: 0.25rem;
 72→		}
 73→		.connection-provider {
 74→			font-weight: 600;
 75→			font-size: 0.875rem;
 76→		}
 77→		.connection-date {
 78→			font-size: 0.75rem;
 79→			color: var(--muted-foreground, #6b7280);
 80→		}
 81→		.connection-expired {
 82→			font-size: 0.75rem;
 83→			color: var(--destructive, #dc2626);
 84→			font-weight: 500;
 85→		}
 86→		.available-providers {
 87→			display: flex;
 88→			flex-direction: column;
