 1→/**
 2→ * PKCE utilities for OAuth flows.
 3→ *
 4→ * Generates code verifier and challenge for Proof Key for Code Exchange (RFC 7636)
 5→ */
 6→
 7→import { webcrypto } from "node:crypto";
 8→
 9→/**
10→ * Encode bytes as base64url string.
11→ */
12→function base64urlEncode(bytes: Uint8Array): string {
13→	let binary = "";
14→	for (const byte of bytes) {
15→		binary += String.fromCharCode(byte);
16→	}
17→	return Buffer.from(binary, "binary")
18→		.toString("base64")
19→		.replace(/\+/g, "-")
20→		.replace(/\//g, "_")
21→		.replace(/=/g, "");
22→}
23→
24→/**
25→ * Generate PKCE code verifier and challenge.
26→ * Uses Web Crypto API for cross-platform compatibility.
27→ */
28→export async function generatePKCE(): Promise<{
29→	verifier: string;
30→	challenge: string;
31→}> {
32→	// Generate random verifier
33→	const verifierBytes = new Uint8Array(32);
34→	webcrypto.getRandomValues(verifierBytes);
35→	const verifier = base64urlEncode(verifierBytes);
36→
37→	// Compute SHA-256 challenge
38→	const encoder = new TextEncoder();
39→	const data = encoder.encode(verifier);
40→	const hashBuffer = await webcrypto.subtle.digest("SHA-256", data);
41→	const challenge = base64urlEncode(new Uint8Array(hashBuffer));
42→
43→	return { verifier, challenge };
44→}
