208→		}
209→	`;
210→
211→	@property({ type: Function })
212→	getToken: (() => string | null) | undefined;
213→
214→	@state()
215→	private connections: OAuthConnectionInfo[] = [];
216→
217→	@state()
218→	private loading = false;
219→
220→	@state()
221→	private connecting: Record<string, boolean> = {};
222→
223→	@state()
224→	private statusMessage = "";
225→
226→	@state()
227→	private statusType: "success" | "error" = "success";
228→
229→	/** Provider currently awaiting a pasted auth code */
230→	@state()
231→	private pendingCodeProvider: string | null = null;
232→
233→	/** The OAuth state token for the pending code exchange */
234→	private pendingState: string | null = null;
235→
236→	/** Reference to the open OAuth popup */
237→	private oauthPopup: Window | null = null;
238→
239→	override connectedCallback() {
240→		super.connectedCallback();
241→		this.loadConnections();
242→	}
243→
244→	private fetchApi = (url: string, options?: RequestInit) => apiFetch(url, options, this.getToken);
245→
246→	private async loadConnections() {
247→		this.loading = true;
248→		try {
249→			const result = await this.fetchApi("/api/oauth");
250→			if (result.success) {
251→				this.connections = result.data.credentials;
252→			}
253→		} catch (err) {
254→			console.error("Failed to load OAuth connections:", err);
255→		} finally {
256→			this.loading = false;
257→		}
258→	}
259→
260→	private async handleConnect(provider: string) {
261→		this.connecting = { ...this.connecting, [provider]: true };
262→		this.statusMessage = "";
263→
264→		try {
265→			// Start OAuth flow
266→			const startResult = await this.fetchApi(`/api/oauth/${provider}/start`, {
267→				method: "POST",
268→			});
269→
270→			if (!startResult.success) {
271→				this.statusMessage = startResult.error || "Failed to start OAuth flow";
272→				this.statusType = "error";
273→				this.connecting = { ...this.connecting, [provider]: false };
274→				return;
275→			}
276→
277→			const { authUrl, state } = startResult.data;
278→
279→			// Open OAuth URL in popup
280→			const popup = window.open(
281→				authUrl,
282→				"oauth_popup",
283→				"width=600,height=700,left=100,top=100"
284→			);
285→
286→			if (!popup) {
287→				this.statusMessage = "Please allow popups to connect";
288→				this.statusType = "error";
289→				this.connecting = { ...this.connecting, [provider]: false };
290→				return;
291→			}
292→
293→			// Store state and show inline code input
294→			this.oauthPopup = popup;
295→			this.pendingState = state;
296→			this.pendingCodeProvider = provider;
297→			// connecting state stays true — cleared when code is submitted or cancelled
298→		} catch (err) {
299→			console.error("OAuth connection error:", err);
300→			this.statusMessage = "Network error";
301→			this.statusType = "error";
302→			this.connecting = { ...this.connecting, [provider]: false };
303→		}
304→	}
305→
306→	private async handleCodeSubmit() {
307→		const provider = this.pendingCodeProvider;
308→		const state = this.pendingState;
309→		if (!provider || !state) return;
310→
311→		const input = this.shadowRoot?.querySelector<HTMLInputElement>("#oauth-code-input");
312→		const rawCode = input?.value?.trim();
313→		if (!rawCode) return;
314→
315→		// Extract code from "code#state" format that some providers use
316→		const code = rawCode.split("#")[0];
317→
318→		// Close popup if still open
319→		if (this.oauthPopup && !this.oauthPopup.closed) {
320→			this.oauthPopup.close();
321→		}
322→
323→		// Clear the pending state
324→		this.pendingCodeProvider = null;
325→		this.pendingState = null;
326→		this.oauthPopup = null;
327→
