212→function startLocalOAuthServer(state: string): Promise<OAuthServerInfo> {
213→	if (!_http) {
214→		throw new Error("OpenAI Codex OAuth is only available in Node.js environments");
215→	}
216→	let lastCode: string | null = null;
217→	let cancelled = false;
218→	const server = _http.createServer((req, res) => {
219→		try {
220→			const url = new URL(req.url || "", "http://localhost");
221→			if (url.pathname !== "/auth/callback") {
222→				res.statusCode = 404;
223→				res.end("Not found");
224→				return;
225→			}
226→			if (url.searchParams.get("state") !== state) {
227→				res.statusCode = 400;
228→				res.end("State mismatch");
229→				return;
230→			}
231→			const code = url.searchParams.get("code");
232→			if (!code) {
233→				res.statusCode = 400;
234→				res.end("Missing authorization code");
235→				return;
236→			}
237→			res.statusCode = 200;
238→			res.setHeader("Content-Type", "text/html; charset=utf-8");
239→			res.end(SUCCESS_HTML);
240→			lastCode = code;
241→		} catch {
242→			res.statusCode = 500;
243→			res.end("Internal error");
244→		}
245→	});
246→
247→	return new Promise((resolve) => {
248→		server
249→			.listen(1455, "127.0.0.1", () => {
250→				resolve({
251→					close: () => server.close(),
252→					cancelWait: () => {
253→						cancelled = true;
254→					},
255→					waitForCode: async () => {
256→						const sleep = () => new Promise((r) => setTimeout(r, 100));
257→						for (let i = 0; i < 600; i += 1) {
258→							if (lastCode) return { code: lastCode };
259→							if (cancelled) return null;
260→							await sleep();
261→						}
262→						return null;
263→					},
264→				});
265→			})
266→			.on("error", (err: NodeJS.ErrnoException) => {
267→				console.error(
268→					"[openai-codex] Failed to bind http://127.0.0.1:1455 (",
269→					err.code,
270→					") Falling back to manual paste.",
271→				);
272→				resolve({
273→					close: () => {
274→						try {
275→							server.close();
276→						} catch {
277→							// ignore
278→						}
279→					},
280→					cancelWait: () => {},
281→					waitForCode: async () => null,
282→				});
283→			});
284→	});
285→}
