287→function getAccountId(accessToken: string): string | null {
288→	const payload = decodeJwt(accessToken);
289→	const auth = payload?.[JWT_CLAIM_PATH];
290→	const accountId = auth?.chatgpt_account_id;
291→	return typeof accountId === "string" && accountId.length > 0 ? accountId : null;
292→}
