294→/**
295→ * Login with OpenAI Codex OAuth
296→ *
297→ * @param options.onAuth - Called with URL and instructions when auth starts
298→ * @param options.onPrompt - Called to prompt user for manual code paste (fallback if no onManualCodeInput)
299→ * @param options.onProgress - Optional progress messages
300→ * @param options.onManualCodeInput - Optional promise that resolves with user-pasted code.
301→ *                                    Races with browser callback - whichever completes first wins.
302→ *                                    Useful for showing paste input immediately alongside browser flow.
303→ * @param options.originator - OAuth originator parameter (defaults to "pi")
304→ */
305→export async function loginOpenAICodex(options: {
306→	onAuth: (info: { url: string; instructions?: string }) => void;
307→	onPrompt: (prompt: OAuthPrompt) => Promise<string>;
308→	onProgress?: (message: string) => void;
309→	onManualCodeInput?: () => Promise<string>;
310→	originator?: string;
311→}): Promise<OAuthCredentials> {
312→	const { verifier, state, url } = await createAuthorizationFlow(options.originator);
313→	const server = await startLocalOAuthServer(state);
314→
315→	options.onAuth({ url, instructions: "A browser window should open. Complete login to finish." });
316→
317→	let code: string | undefined;
318→	try {
319→		if (options.onManualCodeInput) {
320→			// Race between browser callback and manual input
321→			let manualCode: string | undefined;
322→			let manualError: Error | undefined;
323→			const manualPromise = options
324→				.onManualCodeInput()
325→				.then((input) => {
326→					manualCode = input;
327→					server.cancelWait();
328→				})
329→				.catch((err) => {
330→					manualError = err instanceof Error ? err : new Error(String(err));
331→					server.cancelWait();
332→				});
333→
334→			const result = await server.waitForCode();
335→
336→			// If manual input was cancelled, throw that error
337→			if (manualError) {
338→				throw manualError;
339→			}
340→
341→			if (result?.code) {
342→				// Browser callback won
343→				code = result.code;
344→			} else if (manualCode) {
345→				// Manual input won (or callback timed out and user had entered code)
346→				const parsed = parseAuthorizationInput(manualCode);
347→				if (parsed.state && parsed.state !== state) {
348→					throw new Error("State mismatch");
349→				}
350→				code = parsed.code;
351→			}
352→
353→			// If still no code, wait for manual promise to complete and try that
354→			if (!code) {
355→				await manualPromise;
356→				if (manualError) {
357→					throw manualError;
358→				}
359→				if (manualCode) {
360→					const parsed = parseAuthorizationInput(manualCode);
361→					if (parsed.state && parsed.state !== state) {
362→						throw new Error("State mismatch");
363→					}
364→					code = parsed.code;
365→				}
366→			}
367→		} else {
368→			// Original flow: wait for callback, then prompt if needed
369→			const result = await server.waitForCode();
370→			if (result?.code) {
371→				code = result.code;
372→			}
373→		}
374→
375→		// Fallback to onPrompt if still no code
376→		if (!code) {
377→			const input = await options.onPrompt({
378→				message: "Paste the authorization code (or full redirect URL):",
379→			});
380→			const parsed = parseAuthorizationInput(input);
381→			if (parsed.state && parsed.state !== state) {
382→				throw new Error("State mismatch");
383→			}
384→			code = parsed.code;
385→		}
386→
387→		if (!code) {
388→			throw new Error("Missing authorization code");
389→		}
390→
391→		const tokenResult = await exchangeAuthorizationCode(code, verifier);
392→		if (tokenResult.type !== "success") {
393→			throw new Error("Token exchange failed");
394→		}
395→
396→		const accountId = getAccountId(tokenResult.access);
397→		if (!accountId) {
398→			throw new Error("Failed to extract accountId from token");
399→		}
400→
401→		return {
402→			access: tokenResult.access,
403→			refresh: tokenResult.refresh,
404→			expires: tokenResult.expires,
405→			accountId,
406→		};
407→	} finally {
408→		server.close();
409→	}
410→}
411→
412→/**
413→ * Refresh OpenAI Codex OAuth token
414→ */
415→export async function refreshOpenAICodexToken(refreshToken: string): Promise<OAuthCredentials> {
416→	const result = await refreshAccessToken(refreshToken);
417→	if (result.type !== "success") {
418→		throw new Error("Failed to refresh OpenAI Codex token");
419→	}
420→
421→	const accountId = getAccountId(result.access);
422→	if (!accountId) {
423→		throw new Error("Failed to extract accountId from token");
424→	}
425→
426→	return {
427→		access: result.access,
428→		refresh: result.refresh,
429→		expires: result.expires,
430→		accountId,
431→	};
432→}
433→
434→export const openaiCodexOAuthProvider: OAuthProviderInterface = {
435→	id: "openai-codex",
436→	name: "ChatGPT Plus/Pro (Codex Subscription)",
437→	usesCallbackServer: true,
438→
439→	async login(callbacks: OAuthLoginCallbacks): Promise<OAuthCredentials> {
440→		return loginOpenAICodex({
441→			onAuth: callbacks.onAuth,
442→			onPrompt: callbacks.onPrompt,
443→			onProgress: callbacks.onProgress,
444→			onManualCodeInput: callbacks.onManualCodeInput,
445→		});
446→	},
447→
448→	async refreshToken(credentials: OAuthCredentials): Promise<OAuthCredentials> {
449→		return refreshOpenAICodexToken(credentials.refresh);
450→	},
451→
452→	getApiKey(credentials: OAuthCredentials): string {
453→		return credentials.access;
454→	},
455→};
