	const WS_MAX_PER_USER = 5;

	// Track active CWDs per user (for agent-files endpoint)
	const activeUserCwds = new Map<string, string>();

	// --- OAuth callback (public, no auth — popup redirect from OAuth provider) ---
	// The popup gets redirected here by OpenAI with ?code=...&state=...
	// We relay code+state to the opener window via postMessage so the
	// authenticated client can complete the token exchange.
	app.get("/auth/openai-callback", (_req, res) => {
		res.setHeader("Content-Type", "text/html; charset=utf-8");
		res.send(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>Authorization</title></head>
<body>
<p id="msg">Completing authorization…</p>
<script>
(function(){
  var params = new URLSearchParams(location.search);
  var code = params.get("code");
  var state = params.get("state");
  if (code && state && window.opener) {
    window.opener.postMessage({ type: "oauth-callback", code: code, state: state }, "*");
    document.getElementById("msg").textContent = "Authorization complete — you can close this window.";
  } else if (code) {
    document.getElementById("msg").textContent = "Authorization code: " + code + "\\nPaste this in the app to finish connecting.";
  } else {
    document.getElementById("msg").textContent = "Authorization failed — no code received.";
  }
})();
</script>
</body></html>`);
	});

	// --- API Routes ---
	app.use("/api/auth", authRateLimit, authRouter);
	app.use("/api/sessions", apiRateLimit, createSessionsRouter(sessionStatusService, sessionPool));
	app.use("/api/settings", requireAuth, apiRateLimit, settingsRouter);
	app.use("/api/import", requireAuth, apiRateLimit, importRouter);
	app.use("/api/provider-keys", apiRateLimit, createProviderKeysRouter(crypto));
	app.use("/api/skills", apiRateLimit, createSkillsRouter(storageService));

