// --- OAuth callback server on port 1455 ---
// OpenAI's public OAuth client only allows http://localhost:1455/auth/callback
// as a redirect URI. This lightweight server captures the redirect and relays
// the authorization code to the opener window via postMessage.
const OAUTH_CALLBACK_PORT = 1455;
let oauthCallbackServer: ReturnType<typeof createServer> | null = null;
if (!process.env.OAUTH_OPENAI_REDIRECT_URI) {
	oauthCallbackServer = createServer((req, res) => {
		const url = new URL(req.url || "", `http://localhost:${OAUTH_CALLBACK_PORT}`);
		if (url.pathname === "/auth/callback") {
			res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
			res.end(OAUTH_CALLBACK_HTML);
		} else {
			res.writeHead(404);
			res.end("Not found");
		}
	});
	oauthCallbackServer.listen(OAUTH_CALLBACK_PORT, "127.0.0.1", () => {
		console.log(`[server] OAuth callback server on http://localhost:${OAUTH_CALLBACK_PORT}`);
	});
	oauthCallbackServer.on("error", (err: NodeJS.ErrnoException) => {
		if (err.code === "EADDRINUSE") {
			console.warn(`[server] Port ${OAUTH_CALLBACK_PORT} in use — OAuth callback server skipped (manual code paste still works)`);
		} else {
			console.error("[server] OAuth callback server error:", err);
		}
		oauthCallbackServer = null;
	});
}

// Graceful shutdown
