  6→import { getModels, getProviders, type Model, modelsAreEqual } from "@mariozechner/pi-ai";
  7→import { html, type PropertyValues, type TemplateResult } from "lit";
  8→import { customElement, state } from "lit/decorators.js";
  9→import { createRef, ref } from "lit/directives/ref.js";
 10→import { Brain, Image as ImageIcon } from "lucide";
 11→import { Input } from "../components/Input.js";
 12→import { getAppStorage } from "../storage/app-storage.js";
 13→import type { AutoDiscoveryProviderType } from "../storage/stores/custom-providers-store.js";
