 17→
 18→@customElement("agent-model-selector")
 19→export class ModelSelector extends DialogBase {
 20→	@state() currentModel: Model<any> | null = null;
 21→	@state() searchQuery = "";
 22→	@state() filterThinking = false;
 23→	@state() filterVision = false;
 24→	@state() customProvidersLoading = false;
 25→	@state() selectedIndex = 0;
 26→	@state() private navigationMode: "mouse" | "keyboard" = "mouse";
 27→	@state() private customProviderModels: Model<any>[] = [];
 28→
 29→	private onSelectCallback?: (model: Model<any>) => void;
 30→	private scrollContainerRef = createRef<HTMLDivElement>();
 31→	private searchInputRef = createRef<HTMLInputElement>();
 32→	private lastMousePosition = { x: 0, y: 0 };
 33→
 34→	protected override modalWidth = "min(400px, 90vw)";
 35→
 36→	static async open(currentModel: Model<any> | null, onSelect: (model: Model<any>) => void) {
 37→		const selector = new ModelSelector();
 38→		selector.currentModel = currentModel;
 39→		selector.onSelectCallback = onSelect;
 40→		selector.open();
 41→		selector.loadCustomProviders();
 42→	}
 43→
 44→	override async firstUpdated(changedProperties: PropertyValues): Promise<void> {
 45→		super.firstUpdated(changedProperties);
 46→		// Wait for dialog to be fully rendered
 47→		await this.updateComplete;
 48→		// Focus the search input when dialog opens
 49→		this.searchInputRef.value?.focus();
 50→
 51→		// Track actual mouse movement
 52→		this.addEventListener("mousemove", (e: MouseEvent) => {
 53→			// Check if mouse actually moved
 54→			if (e.clientX !== this.lastMousePosition.x || e.clientY !== this.lastMousePosition.y) {
 55→				this.lastMousePosition = { x: e.clientX, y: e.clientY };
 56→				// Only switch to mouse mode on actual mouse movement
 57→				if (this.navigationMode === "keyboard") {
 58→					this.navigationMode = "mouse";
 59→					// Update selection to the item under the mouse
 60→					const target = e.target as HTMLElement;
 61→					const modelItem = target.closest("[data-model-item]");
 62→					if (modelItem) {
 63→						const allItems = this.scrollContainerRef.value?.querySelectorAll("[data-model-item]");
 64→						if (allItems) {
 65→							const index = Array.from(allItems).indexOf(modelItem);
 66→							if (index !== -1) {
 67→								this.selectedIndex = index;
 68→							}
 69→						}
 70→					}
 71→				}
 72→			}
 73→		});
 74→
 75→		// Add global keyboard handler for the dialog
 76→		this.addEventListener("keydown", (e: KeyboardEvent) => {
 77→			// Get filtered models to know the bounds
 78→			const filteredModels = this.getFilteredModels();
 79→
 80→			if (e.key === "ArrowDown") {
 81→				e.preventDefault();
 82→				this.navigationMode = "keyboard";
 83→				this.selectedIndex = Math.min(this.selectedIndex + 1, filteredModels.length - 1);
 84→				this.scrollToSelected();
 85→			} else if (e.key === "ArrowUp") {
 86→				e.preventDefault();
 87→				this.navigationMode = "keyboard";
 88→				this.selectedIndex = Math.max(this.selectedIndex - 1, 0);
 89→				this.scrollToSelected();
 90→			} else if (e.key === "Enter") {
 91→				e.preventDefault();
 92→				if (filteredModels[this.selectedIndex]) {
 93→					this.handleSelect(filteredModels[this.selectedIndex].model);
 94→				}
 95→			}
 96→		});
 97→	}
 98→
 99→	private async loadCustomProviders() {
100→		this.customProvidersLoading = true;
101→		const allCustomModels: Model<any>[] = [];
102→
103→		try {
104→			const storage = getAppStorage();
105→			const customProviders = await storage.customProviders.getAll();
106→
107→			// Load models from custom providers
108→			for (const provider of customProviders) {
109→				const isAutoDiscovery: boolean =
110→					provider.type === "ollama" ||
111→					provider.type === "llama.cpp" ||
112→					provider.type === "vllm" ||
113→					provider.type === "lmstudio";
114→
115→				if (isAutoDiscovery) {
116→					try {
117→						const models = await discoverModels(
118→							provider.type as AutoDiscoveryProviderType,
119→							provider.baseUrl,
120→							provider.apiKey,
121→						);
122→
123→						const modelsWithProvider = models.map((model) => ({
124→							...model,
125→							provider: provider.name,
126→						}));
127→
128→						allCustomModels.push(...modelsWithProvider);
129→					} catch (error) {
130→						console.debug(`Failed to load models from ${provider.name}:`, error);
131→					}
132→				} else if (provider.models) {
133→					// Manual provider - models already defined
134→					allCustomModels.push(...provider.models);
135→				}
136→			}
137→		} catch (error) {
138→			console.error("Failed to load custom providers:", error);
139→		} finally {
140→			this.customProviderModels = allCustomModels;
141→			this.customProvidersLoading = false;
142→			this.requestUpdate();
143→		}
144→	}
