21→	provider: TProvider,
22→	modelId: TModelId,
23→): Model<ModelApi<TProvider, TModelId>> {
24→	const providerModels = modelRegistry.get(provider);
25→	return providerModels?.get(modelId as string) as Model<ModelApi<TProvider, TModelId>>;
26→}
