32→export function getModels<TProvider extends KnownProvider>(
33→	provider: TProvider,
34→): Model<ModelApi<TProvider, keyof (typeof MODELS)[TProvider]>>[] {
35→	const models = modelRegistry.get(provider);
36→	return models ? (Array.from(models.values()) as Model<ModelApi<TProvider, keyof (typeof MODELS)[TProvider]>>[]) : [];
37→}
