39→export function calculateCost<TApi extends Api>(model: Model<TApi>, usage: Usage): Usage["cost"] {
40→	usage.cost.input = (model.cost.input / 1000000) * usage.input;
41→	usage.cost.output = (model.cost.output / 1000000) * usage.output;
42→	usage.cost.cacheRead = (model.cost.cacheRead / 1000000) * usage.cacheRead;
43→	usage.cost.cacheWrite = (model.cost.cacheWrite / 1000000) * usage.cacheWrite;
44→	usage.cost.total = usage.cost.input + usage.cost.output + usage.cost.cacheRead + usage.cost.cacheWrite;
45→	return usage.cost;
46→}
