48→/**
49→ * Check if a model supports xhigh thinking level.
50→ *
51→ * Supported today:
52→ * - GPT-5.2 / GPT-5.3 model families
53→ * - Anthropic Messages API Opus 4.6 models (xhigh maps to adaptive effort "max")
54→ */
55→export function supportsXhigh<TApi extends Api>(model: Model<TApi>): boolean {
56→	if (model.id.includes("gpt-5.2") || model.id.includes("gpt-5.3")) {
57→		return true;
58→	}
59→
60→	if (model.api === "anthropic-messages") {
61→		return model.id.includes("opus-4-6") || model.id.includes("opus-4.6");
62→	}
63→
64→	return false;
65→}
