67→/**
68→ * Check if two models are equal by comparing both their id and provider.
69→ * Returns false if either model is null or undefined.
70→ */
71→export function modelsAreEqual<TApi extends Api>(
72→	a: Model<TApi> | null | undefined,
73→	b: Model<TApi> | null | undefined,
74→): boolean {
75→	if (!a || !b) return false;
76→	return a.id === b.id && a.provider === b.provider;
77→}
