23→export interface ApiProvider<TApi extends Api = Api, TOptions extends StreamOptions = StreamOptions> {
24→	api: TApi;
25→	stream: StreamFunction<TApi, TOptions>;
26→	streamSimple: StreamFunction<TApi, SimpleStreamOptions>;
