40→const apiProviderRegistry = new Map<string, RegisteredApiProvider>();
41→
42→function wrapStream<TApi extends Api, TOptions extends StreamOptions>(
43→	api: TApi,
44→	stream: StreamFunction<TApi, TOptions>,
45→): ApiStreamFunction {
46→	return (model, context, options) => {
47→		if (model.api !== api) {
48→			throw new Error(`Mismatched api: ${model.api} expected ${api}`);
49→		}
50→		return stream(model as Model<TApi>, context, options as TOptions);
51→	};
52→}
53→
54→function wrapStreamSimple<TApi extends Api>(
55→	api: TApi,
56→	streamSimple: StreamFunction<TApi, SimpleStreamOptions>,
57→): ApiStreamSimpleFunction {
58→	return (model, context, options) => {
59→		if (model.api !== api) {
60→			throw new Error(`Mismatched api: ${model.api} expected ${api}`);
61→		}
62→		return streamSimple(model as Model<TApi>, context, options);
63→	};
64→}
