66→export function registerApiProvider<TApi extends Api, TOptions extends StreamOptions>(
67→	provider: ApiProvider<TApi, TOptions>,
68→	sourceId?: string,
69→): void {
70→	apiProviderRegistry.set(provider.api, {
71→		provider: {
72→			api: provider.api,
73→			stream: wrapStream(provider.api, provider.stream),
74→			streamSimple: wrapStreamSimple(provider.api, provider.streamSimple),
75→		},
76→		sourceId,
77→	});
78→}
