80→export function getApiProvider(api: Api): ApiProviderInternal | undefined {
81→	return apiProviderRegistry.get(api)?.provider;
82→}
83→
84→export function getApiProviders(): ApiProviderInternal[] {
85→	return Array.from(apiProviderRegistry.values(), (entry) => entry.provider);
86→}
