88→export function unregisterApiProviders(sourceId: string): void {
89→	for (const [api, entry] of apiProviderRegistry.entries()) {
90→		if (entry.sourceId === sourceId) {
91→			apiProviderRegistry.delete(api);
92→		}
93→	}
94→}
95→
96→export function clearApiProviders(): void {
97→	apiProviderRegistry.clear();
98→}
