  1→/**
  2→ * Antigravity OAuth flow (Gemini 3, Claude, GPT-OSS via Google Cloud)
  3→ * Uses different OAuth credentials than google-gemini-cli for access to additional models.
  4→ *
  5→ * NOTE: This module uses Node.js http.createServer for the OAuth callback.
  6→ * It is only intended for CLI use, not browser environments.
  7→ */
  8→
  9→import type { Server } from "node:http";
 10→import { generatePKCE } from "./pkce.js";
 11→import type { OAuthCredentials, OAuthLoginCallbacks, OAuthProviderInterface } from "./types.js";
 12→
 13→type AntigravityCredentials = OAuthCredentials & {
 14→	projectId: string;
 15→};
 16→
 17→let _createServer: typeof import("node:http").createServer | null = null;
 18→let _httpImportPromise: Promise<void> | null = null;
 19→if (typeof process !== "undefined" && (process.versions?.node || process.versions?.bun)) {
 20→	_httpImportPromise = import("node:http").then((m) => {
 21→		_createServer = m.createServer;
 22→	});
 23→}
 24→
 25→// Antigravity OAuth credentials (different from Gemini CLI)
 26→const decode = (s: string) => atob(s);
 27→const CLIENT_ID = decode(
 28→	"REDACTED",
 29→);
 30→const CLIENT_SECRET = decode("REDACTED");
 31→const REDIRECT_URI = "http://localhost:51121/oauth-callback";
 32→
 33→// Antigravity requires additional scopes
 34→const SCOPES = [
 35→	"https://www.googleapis.com/auth/cloud-platform",
 36→	"https://www.googleapis.com/auth/userinfo.email",
 37→	"https://www.googleapis.com/auth/userinfo.profile",
 38→	"https://www.googleapis.com/auth/cclog",
 39→	"https://www.googleapis.com/auth/experimentsandconfigs",
 40→];
 41→
 42→const AUTH_URL = "https://accounts.google.com/o/oauth2/v2/auth";
 43→const TOKEN_URL = "https://oauth2.googleapis.com/token";
 44→
 45→// Fallback project ID when discovery fails
 46→const DEFAULT_PROJECT_ID = "rising-fact-p41fc";
 47→
 48→type CallbackServerInfo = {
 49→	server: Server;
 50→	cancelWait: () => void;
 51→	waitForCode: () => Promise<{ code: string; state: string } | null>;
 52→};
 53→
 54→/**
 55→ * Start a local HTTP server to receive the OAuth callback
 56→ */
 57→async function getNodeCreateServer(): Promise<typeof import("node:http").createServer> {
 58→	if (_createServer) return _createServer;
 59→	if (_httpImportPromise) {
 60→		await _httpImportPromise;
 61→	}
 62→	if (_createServer) return _createServer;
 63→	throw new Error("Antigravity OAuth is only available in Node.js environments");
 64→}
 65→
 66→async function startCallbackServer(): Promise<CallbackServerInfo> {
 67→	const createServer = await getNodeCreateServer();
 68→
 69→	return new Promise((resolve, reject) => {
 70→		let result: { code: string; state: string } | null = null;
 71→		let cancelled = false;
 72→
 73→		const server = createServer((req, res) => {
 74→			const url = new URL(req.url || "", `http://localhost:51121`);
 75→
 76→			if (url.pathname === "/oauth-callback") {
 77→				const code = url.searchParams.get("code");
 78→				const state = url.searchParams.get("state");
 79→				const error = url.searchParams.get("error");
 80→
 81→				if (error) {
 82→					res.writeHead(400, { "Content-Type": "text/html" });
 83→					res.end(
 84→						`<html><body><h1>Authentication Failed</h1><p>Error: ${error}</p><p>You can close this window.</p></body></html>`,
 85→					);
 86→					return;
 87→				}
 88→
 89→				if (code && state) {
 90→					res.writeHead(200, { "Content-Type": "text/html" });
 91→					res.end(
 92→						`<html><body><h1>Authentication Successful</h1><p>You can close this window and return to the terminal.</p></body></html>`,
 93→					);
 94→					result = { code, state };
 95→				} else {
 96→					res.writeHead(400, { "Content-Type": "text/html" });
 97→					res.end(
 98→						`<html><body><h1>Authentication Failed</h1><p>Missing code or state parameter.</p></body></html>`,
 99→					);
100→				}
101→			} else {
102→				res.writeHead(404);
103→				res.end();
104→			}
105→		});
106→
107→		server.on("error", (err) => {
108→			reject(err);
109→		});
110→
111→		server.listen(51121, "127.0.0.1", () => {
112→			resolve({
113→				server,
114→				cancelWait: () => {
115→					cancelled = true;
116→				},
117→				waitForCode: async () => {
118→					const sleep = () => new Promise((r) => setTimeout(r, 100));
119→					while (!result && !cancelled) {
120→						await sleep();
121→					}
122→					return result;
123→				},
124→			});
125→		});
126→	});
127→}
128→
129→/**
130→ * Parse redirect URL to extract code and state
131→ */
132→function parseRedirectUrl(input: string): { code?: string; state?: string } {
133→	const value = input.trim();
134→	if (!value) return {};
135→
136→	try {
137→		const url = new URL(value);
138→		return {
139→			code: url.searchParams.get("code") ?? undefined,
140→			state: url.searchParams.get("state") ?? undefined,
141→		};
142→	} catch {
143→		// Not a URL, return empty
144→		return {};
145→	}
146→}
147→
148→interface LoadCodeAssistPayload {
149→	cloudaicompanionProject?: string | { id?: string };
150→	currentTier?: { id?: string };
151→	allowedTiers?: Array<{ id?: string; isDefault?: boolean }>;
152→}
153→
154→/**
155→ * Discover or provision a project for the user
156→ */
157→async function discoverProject(accessToken: string, onProgress?: (message: string) => void): Promise<string> {
158→	const headers = {
159→		Authorization: `Bearer ${accessToken}`,
160→		"Content-Type": "application/json",
161→		"User-Agent": "google-api-nodejs-client/9.15.1",
162→		"X-Goog-Api-Client": "google-cloud-sdk vscode_cloudshelleditor/0.1",
163→		"Client-Metadata": JSON.stringify({
164→			ideType: "IDE_UNSPECIFIED",
165→			platform: "PLATFORM_UNSPECIFIED",
166→			pluginType: "GEMINI",
167→		}),
168→	};
169→
170→	// Try endpoints in order: prod first, then sandbox
171→	const endpoints = ["https://cloudcode-pa.googleapis.com", "https://daily-cloudcode-pa.sandbox.googleapis.com"];
172→
173→	onProgress?.("Checking for existing project...");
174→
175→	for (const endpoint of endpoints) {
176→		try {
177→			const loadResponse = await fetch(`${endpoint}/v1internal:loadCodeAssist`, {
178→				method: "POST",
179→				headers,
180→				body: JSON.stringify({
181→					metadata: {
182→						ideType: "IDE_UNSPECIFIED",
183→						platform: "PLATFORM_UNSPECIFIED",
184→						pluginType: "GEMINI",
185→					},
186→				}),
187→			});
188→
189→			if (loadResponse.ok) {
190→				const data = (await loadResponse.json()) as LoadCodeAssistPayload;
191→
192→				// Handle both string and object formats
193→				if (typeof data.cloudaicompanionProject === "string" && data.cloudaicompanionProject) {
194→					return data.cloudaicompanionProject;
195→				}
196→				if (
197→					data.cloudaicompanionProject &&
198→					typeof data.cloudaicompanionProject === "object" &&
199→					data.cloudaicompanionProject.id
200→				) {
201→					return data.cloudaicompanionProject.id;
202→				}
203→			}
204→		} catch {
205→			// Try next endpoint
206→		}
207→	}
208→
209→	// Use fallback project ID
210→	onProgress?.("Using default project...");
211→	return DEFAULT_PROJECT_ID;
212→}
213→
214→/**
215→ * Get user email from the access token
216→ */
217→async function getUserEmail(accessToken: string): Promise<string | undefined> {
218→	try {
219→		const response = await fetch("https://www.googleapis.com/oauth2/v1/userinfo?alt=json", {
220→			headers: {
221→				Authorization: `Bearer ${accessToken}`,
222→			},
223→		});
224→
225→		if (response.ok) {
226→			const data = (await response.json()) as { email?: string };
227→			return data.email;
228→		}
229→	} catch {
230→		// Ignore errors, email is optional
231→	}
232→	return undefined;
233→}
234→
235→/**
236→ * Refresh Antigravity token
237→ */
238→export async function refreshAntigravityToken(refreshToken: string, projectId: string): Promise<OAuthCredentials> {
239→	const response = await fetch(TOKEN_URL, {
240→		method: "POST",
241→		headers: { "Content-Type": "application/x-www-form-urlencoded" },
242→		body: new URLSearchParams({
243→			client_id: CLIENT_ID,
244→			client_secret: CLIENT_SECRET,
245→			refresh_token: refreshToken,
246→			grant_type: "refresh_token",
247→		}),
248→	});
249→
250→	if (!response.ok) {
251→		const error = await response.text();
252→		throw new Error(`Antigravity token refresh failed: ${error}`);
253→	}
254→
255→	const data = (await response.json()) as {
256→		access_token: string;
257→		expires_in: number;
258→		refresh_token?: string;
259→	};
260→
261→	return {
262→		refresh: data.refresh_token || refreshToken,
263→		access: data.access_token,
264→		expires: Date.now() + data.expires_in * 1000 - 5 * 60 * 1000,
265→		projectId,
266→	};
267→}
268→
269→/**
270→ * Login with Antigravity OAuth
271→ *
272→ * @param onAuth - Callback with URL and optional instructions
273→ * @param onProgress - Optional progress callback
274→ * @param onManualCodeInput - Optional promise that resolves with user-pasted redirect URL.
275→ *                            Races with browser callback - whichever completes first wins.
276→ */
277→export async function loginAntigravity(
278→	onAuth: (info: { url: string; instructions?: string }) => void,
279→	onProgress?: (message: string) => void,
280→	onManualCodeInput?: () => Promise<string>,
281→): Promise<OAuthCredentials> {
282→	const { verifier, challenge } = await generatePKCE();
283→
284→	// Start local server for callback
285→	onProgress?.("Starting local server for OAuth callback...");
286→	const server = await startCallbackServer();
287→
288→	let code: string | undefined;
289→
290→	try {
291→		// Build authorization URL
292→		const authParams = new URLSearchParams({
293→			client_id: CLIENT_ID,
294→			response_type: "code",
295→			redirect_uri: REDIRECT_URI,
296→			scope: SCOPES.join(" "),
297→			code_challenge: challenge,
298→			code_challenge_method: "S256",
299→			state: verifier,
300→			access_type: "offline",
301→			prompt: "consent",
302→		});
303→
304→		const authUrl = `${AUTH_URL}?${authParams.toString()}`;
305→
306→		// Notify caller with URL to open
307→		onAuth({
308→			url: authUrl,
309→			instructions: "Complete the sign-in in your browser.",
310→		});
311→
312→		// Wait for the callback, racing with manual input if provided
313→		onProgress?.("Waiting for OAuth callback...");
314→
315→		if (onManualCodeInput) {
316→			// Race between browser callback and manual input
317→			let manualInput: string | undefined;
318→			let manualError: Error | undefined;
319→			const manualPromise = onManualCodeInput()
320→				.then((input) => {
321→					manualInput = input;
322→					server.cancelWait();
323→				})
324→				.catch((err) => {
325→					manualError = err instanceof Error ? err : new Error(String(err));
326→					server.cancelWait();
327→				});
328→
329→			const result = await server.waitForCode();
330→
331→			// If manual input was cancelled, throw that error
332→			if (manualError) {
333→				throw manualError;
334→			}
335→
