 26→		tokenUrl: "https://console.anthropic.com/v1/oauth/token",
 27→		redirectUri: "https://console.anthropic.com/oauth/code/callback",
 28→		scopes: "org:create_api_key user:profile user:inference",
 29→	},
 30→	"openai-codex": {
 31→		clientId: "app_EMoamEEZ73f0CkXaXp7hrann",
 32→		authorizeUrl: "https://auth.openai.com/oauth/authorize",
 33→		tokenUrl: "https://auth.openai.com/oauth/token",
 34→		redirectUri: OPENAI_REDIRECT_URI,
 35→		scopes: "openid profile email offline_access",
 36→	},
 37→};
 38→
 39→// Temporary storage for PKCE verifiers (in production, use Redis)
 40→const pkceStorage = new Map<string, { verifier: string; userId: string; expiresAt: number }>();
 41→
 42→// Clean up expired PKCE entries every 10 minutes
 43→setInterval(() => {
 44→	const now = Date.now();
 45→	for (const [key, value] of pkceStorage.entries()) {
 46→		if (value.expiresAt < now) {
 47→			pkceStorage.delete(key);
 48→		}
