 59→	router.use(requireAuth);
 60→
 61→	// -----------------------------------------------------------------------
 62→	// POST /:provider/start — Start OAuth flow for any provider
 63→	// -----------------------------------------------------------------------
 64→	router.post("/:provider/start", async (req: Request, res: Response) => {
