122→	// -----------------------------------------------------------------------
123→	// POST /:provider/callback — Handle OAuth callback with authorization code
124→	// -----------------------------------------------------------------------
125→	router.post("/:provider/callback", async (req: Request, res: Response) => {
126→		try {
127→			const { provider } = req.params;
128→			const { code, state } = req.body;
129→			const userId = req.user!.userId;
130→
131→			// Validate provider
132→			// @ts-expect-error Express 5 params type is string | string[]
133→			if (!(provider in OAUTH_PROVIDERS)) {
