  1→/**
  2→ * OAuth credential management service.
  3→ *
  4→ * Handles storage, retrieval, and automatic refresh of OAuth credentials
  5→ * for subscription-based LLM providers (Anthropic Claude Pro, OpenAI Codex, etc.)
  6→ */
  7→
  8→import type { Pool } from "pg";
  9→import type { CryptoService } from "./crypto.js";
 10→import { getOAuthApiKey } from "@mariozechner/pi-ai/oauth";
 11→
 12→export interface OAuthCredentials {
 13→	refresh: string;
 14→	access: string;
 15→	expires: number; // Expiration timestamp in milliseconds
 16→	[key: string]: unknown;
 17→}
 18→
 19→export interface StoredOAuthCredential {
 20→	id: string;
 21→	userId?: string;
 22→	teamId?: string;
 23→	provider: string;
 24→	expiresAt: Date;
 25→	createdAt: Date;
 26→	updatedAt: Date;
 27→}
 28→
 29→interface OAuthCredentialRow {
 30→	id: string;
 31→	user_id?: string;
 32→	team_id?: string;
 33→	provider: string;
 34→	encrypted_dek: Buffer;
 35→	encrypted_refresh: Buffer;
 36→	encrypted_access: Buffer;
 37→	iv: Buffer;
 38→	expires_at: Date;
 39→	key_version: number;
 40→	created_at: Date;
 41→	updated_at: Date;
 42→}
 43→
 44→export type OAuthProviderId =
 45→	| "anthropic"
 46→	| "openai-codex"
 47→	| "github-copilot"
 48→	| "google-gemini-cli"
 49→	| "google-antigravity";
 50→
 51→export class OAuthService {
 52→	constructor(
 53→		private db: Pool,
 54→		private crypto: CryptoService,
 55→	) {}
 56→
 57→	/**
 58→	 * Store OAuth credentials for a user or team.
 59→	 * Credentials are encrypted using envelope encryption.
 60→	 */
 61→	async storeCredentials(
 62→		provider: OAuthProviderId,
 63→		credentials: OAuthCredentials,
 64→		options: { userId?: string; teamId?: string },
 65→	): Promise<void> {
 66→		if (!options.userId && !options.teamId) {
 67→			throw new Error("Either userId or teamId must be provided");
 68→		}
 69→		if (options.userId && options.teamId) {
 70→			throw new Error("Cannot specify both userId and teamId");
 71→		}
 72→
 73→		// Encrypt both tokens as a single blob so they share the same DEK/IV.
 74→		// The encrypted_refresh column stores the combined blob; encrypted_access
 75→		// is set to an empty buffer (kept for schema compatibility).
 76→		const combined = JSON.stringify({ refresh: credentials.refresh, access: credentials.access });
 77→		const envelope = this.crypto.encrypt(combined);
 78→
 79→		const expiresAt = new Date(credentials.expires);
 80→
 81→		const conflictColumn = options.userId ? "user_id" : "team_id";
 82→		const result = await this.db.query(
 83→			`INSERT INTO oauth_credentials
 84→			 (user_id, team_id, provider, encrypted_dek, encrypted_refresh, encrypted_access, iv, expires_at, key_version)
 85→			 VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
 86→			 ON CONFLICT (${conflictColumn}, provider)
 87→			 DO UPDATE SET
 88→			   encrypted_dek = $4,
 89→			   encrypted_refresh = $5,
 90→			   encrypted_access = $6,
 91→			   iv = $7,
 92→			   expires_at = $8,
 93→			   key_version = $9,
 94→			   updated_at = now()
 95→			 RETURNING id`,
 96→			[
 97→				options.userId || null,
 98→				options.teamId || null,
 99→				provider,
100→				envelope.encryptedDek,
101→				envelope.encryptedData,
102→				Buffer.alloc(0),
103→				envelope.iv,
104→				expiresAt,
105→				envelope.keyVersion,
106→			],
107→		);
108→
109→		// Audit log
110→		await this.db.query(
111→			`INSERT INTO oauth_audit_log (user_id, team_id, provider, action)
112→			 VALUES ($1, $2, $3, $4)`,
113→			[options.userId || null, options.teamId || null, provider, "store"],
114→		);
115→
116→		console.log(`[oauth-service] Stored credentials for provider=${provider}, id=${result.rows[0].id}`);
117→	}
118→
119→	/**
120→	 * Retrieve OAuth credentials for a user or team.
121→	 * Returns null if no credentials found.
122→	 */
123→	async getCredentials(
124→		provider: OAuthProviderId,
125→		options: { userId?: string; teamId?: string },
126→	): Promise<OAuthCredentials | null> {
127→		if (!options.userId && !options.teamId) {
128→			throw new Error("Either userId or teamId must be provided");
129→		}
130→
131→		const result = await this.db.query<OAuthCredentialRow>(
132→			`SELECT * FROM oauth_credentials
133→			 WHERE provider = $1
134→			   AND (user_id = $2 OR team_id = $3)
135→			 LIMIT 1`,
136→			[provider, options.userId || null, options.teamId || null],
137→		);
138→
139→		if (result.rows.length === 0) {
140→			return null;
141→		}
142→
143→		const row = result.rows[0];
144→
145→		// Decrypt combined token blob (stored in encrypted_refresh column)
146→		const combined = this.crypto.decrypt({
147→			encryptedDek: row.encrypted_dek,
148→			encryptedData: row.encrypted_refresh,
149→			iv: row.iv,
150→			keyVersion: row.key_version,
151→		});
152→
153→		const { refresh, access } = JSON.parse(combined) as { refresh: string; access: string };
154→
155→		return {
156→			refresh,
157→			access,
158→			expires: row.expires_at.getTime(),
159→		};
160→	}
161→
162→	/**
163→	 * Get an API key from OAuth credentials, automatically refreshing if needed.
164→	 * Returns null if no credentials found.
165→	 */
166→	async getApiKey(
167→		provider: OAuthProviderId,
168→		options: { userId?: string; teamId?: string },
169→	): Promise<string | null> {
170→		const credentials = await this.getCredentials(provider, options);
171→		if (!credentials) {
172→			return null;
173→		}
174→
175→		// Use pi-ai's built-in refresh logic (expects a Record keyed by provider ID)
176→		const result = await getOAuthApiKey(provider, { [provider]: credentials });
177→		if (!result) {
178→			return null;
179→		}
180→
181→		// If credentials were refreshed, store the new ones
182→		if (result.newCredentials) {
183→			await this.storeCredentials(provider, result.newCredentials, options);
184→		}
185→
186→		return result.apiKey;
187→	}
188→
189→	/**
190→	 * Delete OAuth credentials for a user or team.
191→	 */
192→	async deleteCredentials(
193→		provider: OAuthProviderId,
194→		options: { userId?: string; teamId?: string },
195→	): Promise<boolean> {
196→		if (!options.userId && !options.teamId) {
197→			throw new Error("Either userId or teamId must be provided");
198→		}
199→
