const PORT = parseInt(process.env.PORT || "3001", 10);
const isDev = process.env.NODE_ENV !== "production";

// OAuth callback HTML — relays code+state to the opener window via postMessage.
// Used by both the main Express route and the port-1455 callback server.
const OAUTH_CALLBACK_HTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>Authorization</title></head>
<body>
<p id="msg">Completing authorization\u2026</p>
<script>
(function(){
  var params = new URLSearchParams(location.search);
  var code = params.get("code");
  var state = params.get("state");
  if (code && state && window.opener) {
    window.opener.postMessage({ type: "oauth-callback", code: code, state: state }, "*");
    document.getElementById("msg").textContent = "Authorization complete \\u2014 you can close this window.";
  } else if (code) {
    document.getElementById("msg").textContent = "Authorization code: " + code + "\\nPaste this in the app to finish connecting.";
  } else {
    document.getElementById("msg").textContent = "Authorization failed \\u2014 no code received.";
  }
})();
</script>
</body></html>`;

function oauthCallbackHandler(_req: any, res: any) {
	res.setHeader("Content-Type", "text/html; charset=utf-8");
	res.end(OAUTH_CALLBACK_HTML);
}

