<title>Authorization</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh;background:#f9fafb;color:#111827}
.card{background:#fff;border-radius:12px;padding:2.5rem;box-shadow:0 1px 3px rgba(0,0,0,.1);text-align:center;max-width:380px;width:90%}
.icon{font-size:3rem;margin-bottom:1rem}
h1{font-size:1.125rem;font-weight:600;margin-bottom:.5rem}
p{color:#6b7280;font-size:.875rem;line-height:1.5}
code{background:#f3f4f6;padding:.125rem .375rem;border-radius:4px;font-size:.8rem;word-break:break-all}
</style>
</head>
<body>
<div class="card">
<div class="icon" id="icon"></div>
<h1 id="title"></h1>
<p id="msg"></p>
</div>
<script>
(function(){
  var p=new URLSearchParams(location.search);
  var code=p.get("code"),state=p.get("state");
  var i=document.getElementById("icon"),t=document.getElementById("title"),m=document.getElementById("msg");
  if(code&&state&&window.opener){
    window.opener.postMessage({type:"oauth-callback",code:code,state:state},"*");
    i.textContent="\\u2705";t.textContent="Authorization Complete";
    m.textContent="You can close this window.";
  }else if(code){
    i.textContent="\\u2705";t.textContent="Authorization Complete";
    m.innerHTML="Paste this code in the app:<br><code>"+code+"</code>";
  }else{
    i.textContent="\\u274c";t.textContent="Authorization Failed";
    m.textContent="No authorization code received.";
  }
})();
</script>
</body></html>`;

