 35→// Provider Registry
 36→// ============================================================================
 37→
 38→import { anthropicOAuthProvider } from "./anthropic.js";
 39→import { githubCopilotOAuthProvider } from "./github-copilot.js";
 40→import { antigravityOAuthProvider } from "./google-antigravity.js";
 41→import { geminiCliOAuthProvider } from "./google-gemini-cli.js";
 42→import { openaiCodexOAuthProvider } from "./openai-codex.js";
 43→import type { OAuthCredentials, OAuthProviderId, OAuthProviderInfo, OAuthProviderInterface } from "./types.js";
 44→
 45→const oauthProviderRegistry = new Map<string, OAuthProviderInterface>([
 46→	[anthropicOAuthProvider.id, anthropicOAuthProvider],
 47→	[githubCopilotOAuthProvider.id, githubCopilotOAuthProvider],
 48→	[geminiCliOAuthProvider.id, geminiCliOAuthProvider],
 49→	[antigravityOAuthProvider.id, antigravityOAuthProvider],
 50→	[openaiCodexOAuthProvider.id, openaiCodexOAuthProvider],
 51→]);
 52→
 53→/**
 54→ * Get an OAuth provider by ID
 55→ */
 56→export function getOAuthProvider(id: OAuthProviderId): OAuthProviderInterface | undefined {
 57→	return oauthProviderRegistry.get(id);
 58→}
 59→
 60→/**
 61→ * Register a custom OAuth provider
 62→ */
 63→export function registerOAuthProvider(provider: OAuthProviderInterface): void {
 64→	oauthProviderRegistry.set(provider.id, provider);
 65→}
