 85→// ============================================================================
 86→// High-level API (uses provider registry)
 87→// ============================================================================
 88→
 89→/**
 90→ * Refresh token for any OAuth provider.
 91→ * @deprecated Use getOAuthProvider(id).refreshToken() instead
 92→ */
 93→export async function refreshOAuthToken(
 94→	providerId: OAuthProviderId,
 95→	credentials: OAuthCredentials,
 96→): Promise<OAuthCredentials> {
 97→	const provider = getOAuthProvider(providerId);
 98→	if (!provider) {
 99→		throw new Error(`Unknown OAuth provider: ${providerId}`);
100→	}
101→	return provider.refreshToken(credentials);
102→}
103→
104→/**
105→ * Get API key for a provider from OAuth credentials.
106→ * Automatically refreshes expired tokens.
107→ *
108→ * @returns API key string and updated credentials, or null if no credentials
109→ * @throws Error if refresh fails
110→ */
111→export async function getOAuthApiKey(
112→	providerId: OAuthProviderId,
113→	credentials: Record<string, OAuthCredentials>,
114→): Promise<{ newCredentials: OAuthCredentials; apiKey: string } | null> {
115→	const provider = getOAuthProvider(providerId);
116→	if (!provider) {
117→		throw new Error(`Unknown OAuth provider: ${providerId}`);
118→	}
119→
120→	let creds = credentials[providerId];
121→	if (!creds) {
122→		return null;
123→	}
124→
125→	// Refresh if expired
126→	if (Date.now() >= creds.expires) {
127→		try {
128→			creds = await provider.refreshToken(creds);
129→		} catch (_error) {
130→			throw new Error(`Failed to refresh OAuth token for ${providerId}`);
131→		}
132→	}
133→
134→	const apiKey = provider.getApiKey(creds);
135→	return { newCredentials: creds, apiKey };
136→}
