  1→/**
  2→ * OpenAI Codex (ChatGPT OAuth) flow
  3→ *
  4→ * NOTE: This module uses Node.js crypto and http for the OAuth callback.
  5→ * It is only intended for CLI use, not browser environments.
  6→ */
  7→
  8→// NEVER convert to top-level imports - breaks browser/Vite builds (web-ui)
  9→let _randomBytes: typeof import("node:crypto").randomBytes | null = null;
 10→let _http: typeof import("node:http") | null = null;
 11→if (typeof process !== "undefined" && (process.versions?.node || process.versions?.bun)) {
 12→	import("node:crypto").then((m) => {
 13→		_randomBytes = m.randomBytes;
 14→	});
 15→	import("node:http").then((m) => {
 16→		_http = m;
 17→	});
 18→}
 19→
 20→import { generatePKCE } from "./pkce.js";
 21→import type { OAuthCredentials, OAuthLoginCallbacks, OAuthPrompt, OAuthProviderInterface } from "./types.js";
 22→
 23→const CLIENT_ID = "app_EMoamEEZ73f0CkXaXp7hrann";
 24→const AUTHORIZE_URL = "https://auth.openai.com/oauth/authorize";
 25→const TOKEN_URL = "https://auth.openai.com/oauth/token";
 26→const REDIRECT_URI = "http://localhost:1455/auth/callback";
 27→const SCOPE = "openid profile email offline_access";
 28→const JWT_CLAIM_PATH = "https://api.openai.com/auth";
 29→
 30→const SUCCESS_HTML = `<!doctype html>
 31→<html lang="en">
 32→<head>
 33→  <meta charset="utf-8" />
 34→  <meta name="viewport" content="width=device-width, initial-scale=1" />
 35→  <title>Authentication successful</title>
 36→</head>
 37→<body>
 38→  <p>Authentication successful. Return to your terminal to continue.</p>
 39→</body>
 40→</html>`;
 41→
 42→type TokenSuccess = { type: "success"; access: string; refresh: string; expires: number };
 43→type TokenFailure = { type: "failed" };
 44→type TokenResult = TokenSuccess | TokenFailure;
 45→
 46→type JwtPayload = {
 47→	[JWT_CLAIM_PATH]?: {
 48→		chatgpt_account_id?: string;
 49→	};
 50→	[key: string]: unknown;
 51→};
 52→
 53→function createState(): string {
 54→	if (!_randomBytes) {
 55→		throw new Error("OpenAI Codex OAuth is only available in Node.js environments");
 56→	}
 57→	return _randomBytes(16).toString("hex");
 58→}
 59→
 60→function parseAuthorizationInput(input: string): { code?: string; state?: string } {
 61→	const value = input.trim();
 62→	if (!value) return {};
 63→
 64→	try {
 65→		const url = new URL(value);
 66→		return {
 67→			code: url.searchParams.get("code") ?? undefined,
 68→			state: url.searchParams.get("state") ?? undefined,
 69→		};
 70→	} catch {
 71→		// not a URL
 72→	}
 73→
 74→	if (value.includes("#")) {
 75→		const [code, state] = value.split("#", 2);
 76→		return { code, state };
 77→	}
 78→
 79→	if (value.includes("code=")) {
 80→		const params = new URLSearchParams(value);
 81→		return {
 82→			code: params.get("code") ?? undefined,
 83→			state: params.get("state") ?? undefined,
 84→		};
 85→	}
 86→
 87→	return { code: value };
 88→}
 89→
 90→function decodeJwt(token: string): JwtPayload | null {
 91→	try {
 92→		const parts = token.split(".");
 93→		if (parts.length !== 3) return null;
 94→		const payload = parts[1] ?? "";
 95→		const decoded = atob(payload);
 96→		return JSON.parse(decoded) as JwtPayload;
 97→	} catch {
 98→		return null;
 99→	}
100→}
101→
102→async function exchangeAuthorizationCode(
103→	code: string,
104→	verifier: string,
105→	redirectUri: string = REDIRECT_URI,
106→): Promise<TokenResult> {
107→	const response = await fetch(TOKEN_URL, {
108→		method: "POST",
109→		headers: { "Content-Type": "application/x-www-form-urlencoded" },
110→		body: new URLSearchParams({
111→			grant_type: "authorization_code",
112→			client_id: CLIENT_ID,
113→			code,
114→			code_verifier: verifier,
115→			redirect_uri: redirectUri,
116→		}),
117→	});
118→
119→	if (!response.ok) {
120→		const text = await response.text().catch(() => "");
121→		console.error("[openai-codex] code->token failed:", response.status, text);
122→		return { type: "failed" };
123→	}
124→
125→	const json = (await response.json()) as {
126→		access_token?: string;
127→		refresh_token?: string;
128→		expires_in?: number;
129→	};
130→
131→	if (!json.access_token || !json.refresh_token || typeof json.expires_in !== "number") {
132→		console.error("[openai-codex] token response missing fields:", json);
133→		return { type: "failed" };
134→	}
135→
136→	return {
137→		type: "success",
138→		access: json.access_token,
139→		refresh: json.refresh_token,
140→		expires: Date.now() + json.expires_in * 1000,
141→	};
142→}
143→
144→async function refreshAccessToken(refreshToken: string): Promise<TokenResult> {
145→	try {
146→		const response = await fetch(TOKEN_URL, {
147→			method: "POST",
148→			headers: { "Content-Type": "application/x-www-form-urlencoded" },
149→			body: new URLSearchParams({
150→				grant_type: "refresh_token",
151→				refresh_token: refreshToken,
152→				client_id: CLIENT_ID,
153→			}),
154→		});
155→
156→		if (!response.ok) {
157→			const text = await response.text().catch(() => "");
158→			console.error("[openai-codex] Token refresh failed:", response.status, text);
159→			return { type: "failed" };
160→		}
161→
162→		const json = (await response.json()) as {
163→			access_token?: string;
164→			refresh_token?: string;
165→			expires_in?: number;
166→		};
167→
168→		if (!json.access_token || !json.refresh_token || typeof json.expires_in !== "number") {
169→			console.error("[openai-codex] Token refresh response missing fields:", json);
170→			return { type: "failed" };
171→		}
172→
173→		return {
174→			type: "success",
175→			access: json.access_token,
176→			refresh: json.refresh_token,
177→			expires: Date.now() + json.expires_in * 1000,
178→		};
179→	} catch (error) {
180→		console.error("[openai-codex] Token refresh error:", error);
181→		return { type: "failed" };
182→	}
183→}
184→
185→async function createAuthorizationFlow(
186→	originator: string = "pi",
187→): Promise<{ verifier: string; state: string; url: string }> {
188→	const { verifier, challenge } = await generatePKCE();
189→	const state = createState();
190→
191→	const url = new URL(AUTHORIZE_URL);
192→	url.searchParams.set("response_type", "code");
193→	url.searchParams.set("client_id", CLIENT_ID);
194→	url.searchParams.set("redirect_uri", REDIRECT_URI);
195→	url.searchParams.set("scope", SCOPE);
196→	url.searchParams.set("code_challenge", challenge);
197→	url.searchParams.set("code_challenge_method", "S256");
198→	url.searchParams.set("state", state);
199→	url.searchParams.set("id_token_add_organizations", "true");
200→	url.searchParams.set("codex_cli_simplified_flow", "true");
201→	url.searchParams.set("originator", originator);
202→
203→	return { verifier, state, url: url.toString() };
204→}
205→
206→type OAuthServerInfo = {
207→	close: () => void;
208→	cancelWait: () => void;
209→	waitForCode: () => Promise<{ code: string } | null>;
210→};
211→
212→function startLocalOAuthServer(state: string): Promise<OAuthServerInfo> {
213→	if (!_http) {
214→		throw new Error("OpenAI Codex OAuth is only available in Node.js environments");
215→	}
216→	let lastCode: string | null = null;
217→	let cancelled = false;
218→	const server = _http.createServer((req, res) => {
219→		try {
220→			const url = new URL(req.url || "", "http://localhost");
221→			if (url.pathname !== "/auth/callback") {
222→				res.statusCode = 404;
223→				res.end("Not found");
224→				return;
225→			}
226→			if (url.searchParams.get("state") !== state) {
227→				res.statusCode = 400;
228→				res.end("State mismatch");
229→				return;
230→			}
231→			const code = url.searchParams.get("code");
232→			if (!code) {
233→				res.statusCode = 400;
234→				res.end("Missing authorization code");
235→				return;
236→			}
237→			res.statusCode = 200;
238→			res.setHeader("Content-Type", "text/html; charset=utf-8");
239→			res.end(SUCCESS_HTML);
240→			lastCode = code;
241→		} catch {
242→			res.statusCode = 500;
243→			res.end("Internal error");
244→		}
245→	});
246→
247→	return new Promise((resolve) => {
248→		server
249→			.listen(1455, "127.0.0.1", () => {
250→				resolve({
251→					close: () => server.close(),
252→					cancelWait: () => {
253→						cancelled = true;
254→					},
255→					waitForCode: async () => {
256→						const sleep = () => new Promise((r) => setTimeout(r, 100));
257→						for (let i = 0; i < 600; i += 1) {
258→							if (lastCode) return { code: lastCode };
259→							if (cancelled) return null;
260→							await sleep();
261→						}
262→						return null;
263→					},
264→				});
265→			})
266→			.on("error", (err: NodeJS.ErrnoException) => {
267→				console.error(
268→					"[openai-codex] Failed to bind http://127.0.0.1:1455 (",
269→					err.code,
270→					") Falling back to manual paste.",
271→				);
272→				resolve({
273→					close: () => {
274→						try {
275→							server.close();
276→						} catch {
277→							// ignore
278→						}
279→					},
280→					cancelWait: () => {},
281→					waitForCode: async () => null,
282→				});
283→			});
284→	});
285→}
286→
287→function getAccountId(accessToken: string): string | null {
288→	const payload = decodeJwt(accessToken);
289→	const auth = payload?.[JWT_CLAIM_PATH];
290→	const accountId = auth?.chatgpt_account_id;
291→	return typeof accountId === "string" && accountId.length > 0 ? accountId : null;
292→}
293→
294→/**
295→ * Login with OpenAI Codex OAuth
296→ *
297→ * @param options.onAuth - Called with URL and instructions when auth starts
298→ * @param options.onPrompt - Called to prompt user for manual code paste (fallback if no onManualCodeInput)
299→ * @param options.onProgress - Optional progress messages
300→ * @param options.onManualCodeInput - Optional promise that resolves with user-pasted code.
301→ *                                    Races with browser callback - whichever completes first wins.
302→ *                                    Useful for showing paste input immediately alongside browser flow.
303→ * @param options.originator - OAuth originator parameter (defaults to "pi")
304→ */
305→export async function loginOpenAICodex(options: {
306→	onAuth: (info: { url: string; instructions?: string }) => void;
307→	onPrompt: (prompt: OAuthPrompt) => Promise<string>;
308→	onProgress?: (message: string) => void;
309→	onManualCodeInput?: () => Promise<string>;
310→	originator?: string;
311→}): Promise<OAuthCredentials> {
312→	const { verifier, state, url } = await createAuthorizationFlow(options.originator);
313→	const server = await startLocalOAuthServer(state);
314→
315→	options.onAuth({ url, instructions: "A browser window should open. Complete login to finish." });
316→
317→	let code: string | undefined;
318→	try {
319→		if (options.onManualCodeInput) {
320→			// Race between browser callback and manual input
321→			let manualCode: string | undefined;
322→			let manualError: Error | undefined;
323→			const manualPromise = options
324→				.onManualCodeInput()
325→				.then((input) => {
326→					manualCode = input;
327→					server.cancelWait();
328→				})
329→				.catch((err) => {
330→					manualError = err instanceof Error ? err : new Error(String(err));
331→					server.cancelWait();
332→				});
333→
334→			const result = await server.waitForCode();
335→
336→			// If manual input was cancelled, throw that error
337→			if (manualError) {
338→				throw manualError;
339→			}
340→
341→			if (result?.code) {
342→				// Browser callback won
343→				code = result.code;
344→			} else if (manualCode) {
345→				// Manual input won (or callback timed out and user had entered code)
346→				const parsed = parseAuthorizationInput(manualCode);
347→				if (parsed.state && parsed.state !== state) {
348→					throw new Error("State mismatch");
349→				}
350→				code = parsed.code;
351→			}
352→
353→			// If still no code, wait for manual promise to complete and try that
354→			if (!code) {
355→				await manualPromise;
356→				if (manualError) {
357→					throw manualError;
358→				}
359→				if (manualCode) {
360→					const parsed = parseAuthorizationInput(manualCode);
361→					if (parsed.state && parsed.state !== state) {
362→						throw new Error("State mismatch");
363→					}
364→					code = parsed.code;
365→				}
366→			}
367→		} else {
368→			// Original flow: wait for callback, then prompt if needed
369→			const result = await server.waitForCode();
370→			if (result?.code) {
371→				code = result.code;
372→			}
373→		}
374→
375→		// Fallback to onPrompt if still no code
376→		if (!code) {
377→			const input = await options.onPrompt({
378→				message: "Paste the authorization code (or full redirect URL):",
379→			});
380→			const parsed = parseAuthorizationInput(input);
381→			if (parsed.state && parsed.state !== state) {
382→				throw new Error("State mismatch");
383→			}
384→			code = parsed.code;
385→		}
386→
387→		if (!code) {
388→			throw new Error("Missing authorization code");
389→		}
390→
391→		const tokenResult = await exchangeAuthorizationCode(code, verifier);
392→		if (tokenResult.type !== "success") {
393→			throw new Error("Token exchange failed");
394→		}
395→
396→		const accountId = getAccountId(tokenResult.access);
397→		if (!accountId) {
398→			throw new Error("Failed to extract accountId from token");
399→		}
400→
401→		return {
402→			access: tokenResult.access,
403→			refresh: tokenResult.refresh,
404→			expires: tokenResult.expires,
405→			accountId,
406→		};
407→	} finally {
408→		server.close();
409→	}
410→}
