  1→/**
  2→ * Gemini CLI OAuth flow (Google Cloud Code Assist)
  3→ * Standard Gemini models only (gemini-2.0-flash, gemini-2.5-*)
  4→ *
  5→ * NOTE: This module uses Node.js http.createServer for the OAuth callback.
  6→ * It is only intended for CLI use, not browser environments.
  7→ */
  8→
  9→import type { Server } from "node:http";
 10→import { generatePKCE } from "./pkce.js";
 11→import type { OAuthCredentials, OAuthLoginCallbacks, OAuthProviderInterface } from "./types.js";
 12→
 13→type GeminiCredentials = OAuthCredentials & {
 14→	projectId: string;
 15→};
 16→
 17→let _createServer: typeof import("node:http").createServer | null = null;
 18→let _httpImportPromise: Promise<void> | null = null;
 19→if (typeof process !== "undefined" && (process.versions?.node || process.versions?.bun)) {
 20→	_httpImportPromise = import("node:http").then((m) => {
 21→		_createServer = m.createServer;
 22→	});
 23→}
 24→
 25→const decode = (s: string) => atob(s);
 26→const CLIENT_ID = decode(
 27→	"REDACTED",
 28→);
 29→const CLIENT_SECRET = decode("REDACTED");
 30→const REDIRECT_URI = "http://localhost:8085/oauth2callback";
 31→const SCOPES = [
 32→	"https://www.googleapis.com/auth/cloud-platform",
 33→	"https://www.googleapis.com/auth/userinfo.email",
 34→	"https://www.googleapis.com/auth/userinfo.profile",
 35→];
 36→const AUTH_URL = "https://accounts.google.com/o/oauth2/v2/auth";
 37→const TOKEN_URL = "https://oauth2.googleapis.com/token";
 38→const CODE_ASSIST_ENDPOINT = "https://cloudcode-pa.googleapis.com";
 39→
 40→type CallbackServerInfo = {
 41→	server: Server;
 42→	cancelWait: () => void;
 43→	waitForCode: () => Promise<{ code: string; state: string } | null>;
 44→};
 45→
 46→/**
 47→ * Start a local HTTP server to receive the OAuth callback
 48→ */
 49→async function getNodeCreateServer(): Promise<typeof import("node:http").createServer> {
 50→	if (_createServer) return _createServer;
 51→	if (_httpImportPromise) {
 52→		await _httpImportPromise;
 53→	}
 54→	if (_createServer) return _createServer;
 55→	throw new Error("Gemini CLI OAuth is only available in Node.js environments");
 56→}
 57→
 58→async function startCallbackServer(): Promise<CallbackServerInfo> {
 59→	const createServer = await getNodeCreateServer();
 60→
 61→	return new Promise((resolve, reject) => {
 62→		let result: { code: string; state: string } | null = null;
 63→		let cancelled = false;
 64→
 65→		const server = createServer((req, res) => {
 66→			const url = new URL(req.url || "", `http://localhost:8085`);
 67→
 68→			if (url.pathname === "/oauth2callback") {
 69→				const code = url.searchParams.get("code");
 70→				const state = url.searchParams.get("state");
 71→				const error = url.searchParams.get("error");
 72→
 73→				if (error) {
 74→					res.writeHead(400, { "Content-Type": "text/html" });
 75→					res.end(
 76→						`<html><body><h1>Authentication Failed</h1><p>Error: ${error}</p><p>You can close this window.</p></body></html>`,
 77→					);
 78→					return;
 79→				}
 80→
 81→				if (code && state) {
 82→					res.writeHead(200, { "Content-Type": "text/html" });
 83→					res.end(
 84→						`<html><body><h1>Authentication Successful</h1><p>You can close this window and return to the terminal.</p></body></html>`,
 85→					);
 86→					result = { code, state };
 87→				} else {
 88→					res.writeHead(400, { "Content-Type": "text/html" });
 89→					res.end(
 90→						`<html><body><h1>Authentication Failed</h1><p>Missing code or state parameter.</p></body></html>`,
 91→					);
 92→				}
 93→			} else {
 94→				res.writeHead(404);
 95→				res.end();
 96→			}
 97→		});
 98→
 99→		server.on("error", (err) => {
100→			reject(err);
101→		});
102→
103→		server.listen(8085, "127.0.0.1", () => {
104→			resolve({
105→				server,
106→				cancelWait: () => {
107→					cancelled = true;
108→				},
109→				waitForCode: async () => {
110→					const sleep = () => new Promise((r) => setTimeout(r, 100));
111→					while (!result && !cancelled) {
112→						await sleep();
113→					}
114→					return result;
115→				},
116→			});
117→		});
118→	});
119→}
