121→/**
122→ * Parse redirect URL to extract code and state
123→ */
124→function parseRedirectUrl(input: string): { code?: string; state?: string } {
125→	const value = input.trim();
126→	if (!value) return {};
127→
128→	try {
129→		const url = new URL(value);
130→		return {
131→			code: url.searchParams.get("code") ?? undefined,
132→			state: url.searchParams.get("state") ?? undefined,
133→		};
134→	} catch {
135→		// Not a URL, return empty
136→		return {};
137→	}
138→}
