140→interface LoadCodeAssistPayload {
141→	cloudaicompanionProject?: string;
142→	currentTier?: { id?: string };
143→	allowedTiers?: Array<{ id?: string; isDefault?: boolean }>;
144→}
145→
146→/**
147→ * Long-running operation response from onboardUser
148→ */
149→interface LongRunningOperationResponse {
150→	name?: string;
151→	done?: boolean;
152→	response?: {
153→		cloudaicompanionProject?: { id?: string };
154→	};
155→}
156→
157→// Tier IDs as used by the Cloud Code API
158→const TIER_FREE = "free-tier";
159→const TIER_LEGACY = "legacy-tier";
160→const TIER_STANDARD = "standard-tier";
161→
162→interface GoogleRpcErrorResponse {
163→	error?: {
164→		details?: Array<{ reason?: string }>;
165→	};
166→}
167→
168→/**
169→ * Wait helper for onboarding retries
170→ */
171→function wait(ms: number): Promise<void> {
172→	return new Promise((resolve) => setTimeout(resolve, ms));
173→}
174→
175→/**
176→ * Get default tier from allowed tiers
177→ */
178→function getDefaultTier(allowedTiers?: Array<{ id?: string; isDefault?: boolean }>): { id?: string } {
179→	if (!allowedTiers || allowedTiers.length === 0) return { id: TIER_LEGACY };
180→	const defaultTier = allowedTiers.find((t) => t.isDefault);
181→	return defaultTier ?? { id: TIER_LEGACY };
182→}
