184→function isVpcScAffectedUser(payload: unknown): boolean {
185→	if (!payload || typeof payload !== "object") return false;
186→	if (!("error" in payload)) return false;
187→	const error = (payload as GoogleRpcErrorResponse).error;
188→	if (!error?.details || !Array.isArray(error.details)) return false;
189→	return error.details.some((detail) => detail.reason === "SECURITY_POLICY_VIOLATED");
190→}
