192→/**
193→ * Poll a long-running operation until completion
194→ */
195→async function pollOperation(
196→	operationName: string,
197→	headers: Record<string, string>,
198→	onProgress?: (message: string) => void,
199→): Promise<LongRunningOperationResponse> {
200→	let attempt = 0;
201→	while (true) {
202→		if (attempt > 0) {
203→			onProgress?.(`Waiting for project provisioning (attempt ${attempt + 1})...`);
204→			await wait(5000);
205→		}
206→
207→		const response = await fetch(`${CODE_ASSIST_ENDPOINT}/v1internal/${operationName}`, {
208→			method: "GET",
209→			headers,
210→		});
211→
212→		if (!response.ok) {
213→			throw new Error(`Failed to poll operation: ${response.status} ${response.statusText}`);
214→		}
215→
216→		const data = (await response.json()) as LongRunningOperationResponse;
217→		if (data.done) {
218→			return data;
219→		}
220→
221→		attempt += 1;
222→	}
223→}
