225→/**
226→ * Discover or provision a Google Cloud project for the user
227→ */
228→async function discoverProject(accessToken: string, onProgress?: (message: string) => void): Promise<string> {
229→	// Check for user-provided project ID via environment variable
230→	const envProjectId = process.env.GOOGLE_CLOUD_PROJECT || process.env.GOOGLE_CLOUD_PROJECT_ID;
231→
232→	const headers = {
233→		Authorization: `Bearer ${accessToken}`,
234→		"Content-Type": "application/json",
235→		"User-Agent": "google-api-nodejs-client/9.15.1",
236→		"X-Goog-Api-Client": "gl-node/22.17.0",
237→	};
238→
239→	// Try to load existing project via loadCodeAssist
240→	onProgress?.("Checking for existing Cloud Code Assist project...");
241→	const loadResponse = await fetch(`${CODE_ASSIST_ENDPOINT}/v1internal:loadCodeAssist`, {
242→		method: "POST",
243→		headers,
244→		body: JSON.stringify({
245→			cloudaicompanionProject: envProjectId,
246→			metadata: {
247→				ideType: "IDE_UNSPECIFIED",
248→				platform: "PLATFORM_UNSPECIFIED",
249→				pluginType: "GEMINI",
250→				duetProject: envProjectId,
251→			},
252→		}),
253→	});
254→
255→	let data: LoadCodeAssistPayload;
256→
257→	if (!loadResponse.ok) {
258→		let errorPayload: unknown;
259→		try {
260→			errorPayload = await loadResponse.clone().json();
261→		} catch {
262→			errorPayload = undefined;
263→		}
264→
265→		if (isVpcScAffectedUser(errorPayload)) {
266→			data = { currentTier: { id: TIER_STANDARD } };
267→		} else {
268→			const errorText = await loadResponse.text();
269→			throw new Error(`loadCodeAssist failed: ${loadResponse.status} ${loadResponse.statusText}: ${errorText}`);
270→		}
271→	} else {
272→		data = (await loadResponse.json()) as LoadCodeAssistPayload;
273→	}
274→
275→	// If user already has a current tier and project, use it
276→	if (data.currentTier) {
277→		if (data.cloudaicompanionProject) {
278→			return data.cloudaicompanionProject;
279→		}
280→		// User has a tier but no managed project - they need to provide one via env var
281→		if (envProjectId) {
282→			return envProjectId;
283→		}
284→		throw new Error(
285→			"This account requires setting the GOOGLE_CLOUD_PROJECT or GOOGLE_CLOUD_PROJECT_ID environment variable. " +
286→				"See https://goo.gle/gemini-cli-auth-docs#workspace-gca",
287→		);
288→	}
289→
290→	// User needs to be onboarded - get the default tier
291→	const tier = getDefaultTier(data.allowedTiers);
292→	const tierId = tier?.id ?? TIER_FREE;
293→
294→	if (tierId !== TIER_FREE && !envProjectId) {
295→		throw new Error(
296→			"This account requires setting the GOOGLE_CLOUD_PROJECT or GOOGLE_CLOUD_PROJECT_ID environment variable. " +
297→				"See https://goo.gle/gemini-cli-auth-docs#workspace-gca",
298→		);
299→	}
300→
301→	onProgress?.("Provisioning Cloud Code Assist project (this may take a moment)...");
302→
303→	// Build onboard request - for free tier, don't include project ID (Google provisions one)
304→	// For other tiers, include the user's project ID if available
305→	const onboardBody: Record<string, unknown> = {
306→		tierId,
307→		metadata: {
308→			ideType: "IDE_UNSPECIFIED",
309→			platform: "PLATFORM_UNSPECIFIED",
310→			pluginType: "GEMINI",
311→		},
312→	};
313→
314→	if (tierId !== TIER_FREE && envProjectId) {
315→		onboardBody.cloudaicompanionProject = envProjectId;
316→		(onboardBody.metadata as Record<string, unknown>).duetProject = envProjectId;
317→	}
318→
319→	// Start onboarding - this returns a long-running operation
320→	const onboardResponse = await fetch(`${CODE_ASSIST_ENDPOINT}/v1internal:onboardUser`, {
321→		method: "POST",
322→		headers,
323→		body: JSON.stringify(onboardBody),
324→	});
325→
326→	if (!onboardResponse.ok) {
327→		const errorText = await onboardResponse.text();
328→		throw new Error(`onboardUser failed: ${onboardResponse.status} ${onboardResponse.statusText}: ${errorText}`);
329→	}
330→
331→	let lroData = (await onboardResponse.json()) as LongRunningOperationResponse;
332→
333→	// If the operation isn't done yet, poll until completion
334→	if (!lroData.done && lroData.name) {
335→		lroData = await pollOperation(lroData.name, headers, onProgress);
336→	}
337→
338→	// Try to get project ID from the response
339→	const projectId = lroData.response?.cloudaicompanionProject?.id;
340→	if (projectId) {
341→		return projectId;
342→	}
343→
344→	// If no project ID from onboarding, fall back to env var
345→	if (envProjectId) {
346→		return envProjectId;
347→	}
348→
349→	throw new Error(
350→		"Could not discover or provision a Google Cloud project. " +
351→			"Try setting the GOOGLE_CLOUD_PROJECT or GOOGLE_CLOUD_PROJECT_ID environment variable. " +
352→			"See https://goo.gle/gemini-cli-auth-docs#workspace-gca",
353→	);
354→}
