377→/**
378→ * Refresh Google Cloud Code Assist token
379→ */
380→export async function refreshGoogleCloudToken(refreshToken: string, projectId: string): Promise<OAuthCredentials> {
381→	const response = await fetch(TOKEN_URL, {
382→		method: "POST",
383→		headers: { "Content-Type": "application/x-www-form-urlencoded" },
384→		body: new URLSearchParams({
385→			client_id: CLIENT_ID,
386→			client_secret: CLIENT_SECRET,
387→			refresh_token: refreshToken,
388→			grant_type: "refresh_token",
389→		}),
390→	});
391→
392→	if (!response.ok) {
393→		const error = await response.text();
394→		throw new Error(`Google Cloud token refresh failed: ${error}`);
395→	}
396→
397→	const data = (await response.json()) as {
398→		access_token: string;
399→		expires_in: number;
400→		refresh_token?: string;
401→	};
402→
403→	return {
404→		refresh: data.refresh_token || refreshToken,
405→		access: data.access_token,
406→		expires: Date.now() + data.expires_in * 1000 - 5 * 60 * 1000,
407→		projectId,
408→	};
409→}
