411→/**
412→ * Login with Gemini CLI (Google Cloud Code Assist) OAuth
413→ *
414→ * @param onAuth - Callback with URL and optional instructions
415→ * @param onProgress - Optional progress callback
416→ * @param onManualCodeInput - Optional promise that resolves with user-pasted redirect URL.
417→ *                            Races with browser callback - whichever completes first wins.
418→ */
419→export async function loginGeminiCli(
420→	onAuth: (info: { url: string; instructions?: string }) => void,
421→	onProgress?: (message: string) => void,
422→	onManualCodeInput?: () => Promise<string>,
423→): Promise<OAuthCredentials> {
424→	const { verifier, challenge } = await generatePKCE();
425→
426→	// Start local server for callback
427→	onProgress?.("Starting local server for OAuth callback...");
428→	const server = await startCallbackServer();
429→
430→	let code: string | undefined;
431→
432→	try {
433→		// Build authorization URL
434→		const authParams = new URLSearchParams({
435→			client_id: CLIENT_ID,
436→			response_type: "code",
437→			redirect_uri: REDIRECT_URI,
438→			scope: SCOPES.join(" "),
439→			code_challenge: challenge,
440→			code_challenge_method: "S256",
441→			state: verifier,
442→			access_type: "offline",
443→			prompt: "consent",
444→		});
445→
446→		const authUrl = `${AUTH_URL}?${authParams.toString()}`;
447→
448→		// Notify caller with URL to open
449→		onAuth({
450→			url: authUrl,
451→			instructions: "Complete the sign-in in your browser.",
452→		});
453→
454→		// Wait for the callback, racing with manual input if provided
455→		onProgress?.("Waiting for OAuth callback...");
456→
457→		if (onManualCodeInput) {
458→			// Race between browser callback and manual input
459→			let manualInput: string | undefined;
460→			let manualError: Error | undefined;
461→			const manualPromise = onManualCodeInput()
462→				.then((input) => {
463→					manualInput = input;
464→					server.cancelWait();
465→				})
466→				.catch((err) => {
467→					manualError = err instanceof Error ? err : new Error(String(err));
468→					server.cancelWait();
469→				});
470→
471→			const result = await server.waitForCode();
472→
473→			// If manual input was cancelled, throw that error
474→			if (manualError) {
475→				throw manualError;
476→			}
477→
478→			if (result?.code) {
479→				// Browser callback won - verify state
480→				if (result.state !== verifier) {
481→					throw new Error("OAuth state mismatch - possible CSRF attack");
482→				}
483→				code = result.code;
484→			} else if (manualInput) {
485→				// Manual input won
486→				const parsed = parseRedirectUrl(manualInput);
487→				if (parsed.state && parsed.state !== verifier) {
488→					throw new Error("OAuth state mismatch - possible CSRF attack");
489→				}
490→				code = parsed.code;
491→			}
492→
493→			// If still no code, wait for manual promise and try that
494→			if (!code) {
495→				await manualPromise;
496→				if (manualError) {
497→					throw manualError;
498→				}
499→				if (manualInput) {
500→					const parsed = parseRedirectUrl(manualInput);
501→					if (parsed.state && parsed.state !== verifier) {
502→						throw new Error("OAuth state mismatch - possible CSRF attack");
503→					}
504→					code = parsed.code;
505→				}
506→			}
507→		} else {
508→			// Original flow: just wait for callback
509→			const result = await server.waitForCode();
510→			if (result?.code) {
511→				if (result.state !== verifier) {
512→					throw new Error("OAuth state mismatch - possible CSRF attack");
513→				}
514→				code = result.code;
515→			}
516→		}
517→
518→		if (!code) {
519→			throw new Error("No authorization code received");
520→		}
521→
522→		// Exchange code for tokens
523→		onProgress?.("Exchanging authorization code for tokens...");
524→		const tokenResponse = await fetch(TOKEN_URL, {
525→			method: "POST",
526→			headers: {
527→				"Content-Type": "application/x-www-form-urlencoded",
528→			},
529→			body: new URLSearchParams({
530→				client_id: CLIENT_ID,
531→				client_secret: CLIENT_SECRET,
532→				code,
533→				grant_type: "authorization_code",
534→				redirect_uri: REDIRECT_URI,
