 21→export async function loginAnthropic(
 22→	onAuthUrl: (url: string) => void,
 23→	onPromptCode: () => Promise<string>,
 24→): Promise<OAuthCredentials> {
 25→	const { verifier, challenge } = await generatePKCE();
 26→
 27→	// Build authorization URL
 28→	const authParams = new URLSearchParams({
 29→		code: "true",
 30→		client_id: CLIENT_ID,
 31→		response_type: "code",
 32→		redirect_uri: REDIRECT_URI,
 33→		scope: SCOPES,
 34→		code_challenge: challenge,
 35→		code_challenge_method: "S256",
 36→		state: verifier,
 37→	});
 38→
 39→	const authUrl = `${AUTHORIZE_URL}?${authParams.toString()}`;
 40→
 41→	// Notify caller with URL to open
 42→	onAuthUrl(authUrl);
 43→
 44→	// Wait for user to paste authorization code (format: code#state)
 45→	const authCode = await onPromptCode();
 46→	const splits = authCode.split("#");
 47→	const code = splits[0];
 48→	const state = splits[1];
 49→
 50→	// Exchange code for tokens
 51→	const tokenResponse = await fetch(TOKEN_URL, {
 52→		method: "POST",
 53→		headers: {
 54→			"Content-Type": "application/json",
 55→		},
 56→		body: JSON.stringify({
 57→			grant_type: "authorization_code",
 58→			client_id: CLIENT_ID,
 59→			code: code,
 60→			state: state,
 61→			redirect_uri: REDIRECT_URI,
 62→			code_verifier: verifier,
 63→		}),
 64→	});
 65→
 66→	if (!tokenResponse.ok) {
 67→		const error = await tokenResponse.text();
 68→		throw new Error(`Token exchange failed: ${error}`);
 69→	}
 70→
 71→	const tokenData = (await tokenResponse.json()) as {
 72→		access_token: string;
 73→		refresh_token: string;
 74→		expires_in: number;
 75→	};
 76→
 77→	// Calculate expiry time (current time + expires_in seconds - 5 min buffer)
 78→	const expiresAt = Date.now() + tokenData.expires_in * 1000 - 5 * 60 * 1000;
 79→
 80→	// Save credentials
 81→	return {
 82→		refresh: tokenData.refresh_token,
 83→		access: tokenData.access_token,
 84→		expires: expiresAt,
 85→	};
