 1→/**
 2→ * PKCE utilities using Web Crypto API.
 3→ * Works in both Node.js 20+ and browsers.
 4→ */
 5→
 6→/**
 7→ * Encode bytes as base64url string.
 8→ */
 9→function base64urlEncode(bytes: Uint8Array): string {
10→	let binary = "";
11→	for (const byte of bytes) {
12→		binary += String.fromCharCode(byte);
13→	}
14→	return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "");
15→}
16→
17→/**
18→ * Generate PKCE code verifier and challenge.
19→ * Uses Web Crypto API for cross-platform compatibility.
20→ */
21→export async function generatePKCE(): Promise<{ verifier: string; challenge: string }> {
22→	// Generate random verifier
23→	const verifierBytes = new Uint8Array(32);
24→	crypto.getRandomValues(verifierBytes);
25→	const verifier = base64urlEncode(verifierBytes);
26→
27→	// Compute SHA-256 challenge
28→	const encoder = new TextEncoder();
29→	const data = encoder.encode(verifier);
30→	const hashBuffer = await crypto.subtle.digest("SHA-256", data);
31→	const challenge = base64urlEncode(new Uint8Array(hashBuffer));
32→
33→	return { verifier, challenge };
34→}
