 69→async function discoverAntigravityProject(accessToken: string): Promise<string> {
 70→	const DEFAULT_PROJECT_ID = "rising-fact-p41fc";
 71→	const headers = {
 72→		Authorization: `Bearer ${accessToken}`,
 73→		"Content-Type": "application/json",
 74→		"User-Agent": "google-api-nodejs-client/9.15.1",
 75→		"X-Goog-Api-Client": "google-cloud-sdk vscode_cloudshelleditor/0.1",
 76→		"Client-Metadata": JSON.stringify({
 77→			ideType: "IDE_UNSPECIFIED",
 78→			platform: "PLATFORM_UNSPECIFIED",
 79→			pluginType: "GEMINI",
 80→		}),
 81→	};
 82→	const body = JSON.stringify({
 83→		metadata: { ideType: "IDE_UNSPECIFIED", platform: "PLATFORM_UNSPECIFIED", pluginType: "GEMINI" },
 84→	});
 85→
 86→	for (const endpoint of [
 87→		"https://cloudcode-pa.googleapis.com",
 88→		"https://daily-cloudcode-pa.sandbox.googleapis.com",
 89→	]) {
 90→		try {
 91→			const res = await fetch(`${endpoint}/v1internal:loadCodeAssist`, { method: "POST", headers, body });
 92→			if (!res.ok) continue;
 93→			const data = (await res.json()) as {
 94→				cloudaicompanionProject?: string | { id?: string };
 95→			};
 96→			if (typeof data.cloudaicompanionProject === "string" && data.cloudaicompanionProject) {
 97→				return data.cloudaicompanionProject;
 98→			}
 99→			if (
100→				data.cloudaicompanionProject &&
101→				typeof data.cloudaicompanionProject === "object" &&
102→				data.cloudaicompanionProject.id
103→			) {
104→				return data.cloudaicompanionProject.id;
105→			}
106→		} catch {
107→			// try next endpoint
108→		}
109→	}
110→	return DEFAULT_PROJECT_ID;
111→}
112→
113→// Temporary storage for PKCE verifiers (in production, use Redis)
114→const pkceStorage = new Map<string, { verifier: string; userId: string; expiresAt: number }>();
115→
116→// Clean up expired PKCE entries every 10 minutes
117→setInterval(() => {
118→	const now = Date.now();
119→	for (const [key, value] of pkceStorage.entries()) {
120→		if (value.expiresAt < now) {
121→			pkceStorage.delete(key);
122→		}
123→	}
124→}, 10 * 60 * 1000);
125→
126→export function createOAuthRouter(crypto: CryptoService): Router {
127→	const router = Router();
128→	const db = getDatabase();
129→	// @ts-expect-error Database wrapper is compatible with Pool for OAuthService usage
130→	const oauthService = new OAuthService(db, crypto);
131→
132→	// All routes require authentication
133→	router.use(requireAuth);
134→
135→	// -----------------------------------------------------------------------
136→	// POST /:provider/start — Start OAuth flow for any provider
137→	// -----------------------------------------------------------------------
138→	router.post("/:provider/start", async (req: Request, res: Response) => {
139→		try {
140→			const { provider } = req.params;
141→			const userId = req.user!.userId;
142→
143→			// Validate provider
144→			// @ts-expect-error Express 5 params type is string | string[]
145→			if (!(provider in OAUTH_PROVIDERS)) {
146→				res.status(400).json({ success: false, error: "Unsupported provider" });
147→				return;
148→			}
149→
150→			const config = OAUTH_PROVIDERS[provider as keyof typeof OAUTH_PROVIDERS];
151→
152→			// Generate PKCE challenge
153→			const { verifier, challenge } = await generatePKCE();
154→
155→			// Store verifier temporarily (expires in 10 minutes)
156→			const stateKey = `${provider}-${userId}-${Date.now()}`;
157→			pkceStorage.set(stateKey, {
158→				verifier,
159→				userId,
160→				expiresAt: Date.now() + 10 * 60 * 1000,
161→			});
162→
163→			// Build authorization URL
164→			const authParams = new URLSearchParams({
165→				client_id: config.clientId,
166→				response_type: "code",
167→				redirect_uri: config.redirectUri,
168→				scope: config.scopes,
169→				code_challenge: challenge,
170→				code_challenge_method: "S256",
171→				state: stateKey,
172→			});
173→
174→			// Provider-specific parameters
175→			if (provider === "openai-codex") {
176→				authParams.set("codex_cli_simplified_flow", "true");
177→				authParams.set("id_token_add_organizations", "true");
178→				authParams.set("originator", "pi");
179→			} else if (provider === "google-antigravity") {
180→				authParams.set("access_type", "offline");
181→				authParams.set("prompt", "consent");
182→			}
183→
184→			const authUrl = `${config.authorizeUrl}?${authParams.toString()}`;
185→
186→			res.json({
187→				success: true,
188→				data: {
189→					authUrl,
190→					state: stateKey,
191→				},
192→			});
193→		} catch (err) {
194→			console.error(`[oauth] POST /:provider/start error:`, err);
195→			res.status(500).json({ success: false, error: "Failed to start OAuth flow" });
196→		}
197→	});
198→
199→	// -----------------------------------------------------------------------
200→	// POST /:provider/callback — Handle OAuth callback with authorization code
201→	// -----------------------------------------------------------------------
202→	router.post("/:provider/callback", async (req: Request, res: Response) => {
203→		try {
204→			const { provider } = req.params;
205→			const { code, state } = req.body;
206→			const userId = req.user!.userId;
207→
208→			// Validate provider
209→			// @ts-expect-error Express 5 params type is string | string[]
210→			if (!(provider in OAUTH_PROVIDERS)) {
211→				res.status(400).json({ success: false, error: "Unsupported provider" });
212→				return;
213→			}
214→
215→			if (!code || typeof code !== "string") {
216→				res.status(400).json({ success: false, error: "code is required" });
217→				return;
218→			}
219→			if (!state || typeof state !== "string") {
220→				res.status(400).json({ success: false, error: "state is required" });
221→				return;
222→			}
223→
224→			// Retrieve and validate PKCE verifier
225→			const pkceData = pkceStorage.get(state);
226→			if (!pkceData) {
227→				res.status(400).json({ success: false, error: "Invalid or expired state" });
228→				return;
229→			}
230→			if (pkceData.userId !== userId) {
231→				res.status(403).json({ success: false, error: "State does not match user" });
232→				return;
233→			}
234→
235→			// Clean up PKCE storage
236→			pkceStorage.delete(state);
237→
238→			const config = OAUTH_PROVIDERS[provider as keyof typeof OAUTH_PROVIDERS];
239→
240→			// Exchange code for tokens
241→			const tokenParams: Record<string, string> = {
242→				grant_type: "authorization_code",
243→				client_id: config.clientId,
244→				code: code,
245→				redirect_uri: config.redirectUri,
246→				code_verifier: pkceData.verifier,
247→			};
248→			if (config.clientSecret) {
249→				tokenParams.client_secret = config.clientSecret;
250→			}
251→
252→			const tokenResponse = await fetch(config.tokenUrl, {
253→				method: "POST",
254→				headers: {
255→					"Content-Type": "application/x-www-form-urlencoded",
256→				},
257→				body: new URLSearchParams(tokenParams),
258→			});
259→
260→			if (!tokenResponse.ok) {
261→				const error = await tokenResponse.text();
262→				console.error(`[oauth] Token exchange failed for ${provider}:`, error);
263→				res.status(400).json({ success: false, error: "Token exchange failed" });
264→				return;
265→			}
266→
267→			const tokenData = (await tokenResponse.json()) as {
268→				access_token: string;
269→				refresh_token: string;
270→				expires_in: number;
271→			};
272→
273→			// Calculate expiry time (current time + expires_in seconds - 5 min buffer)
274→			const expiresAt = Date.now() + tokenData.expires_in * 1000 - 5 * 60 * 1000;
275→
276→			// Build credentials object (with provider-specific extra fields)
277→			const credentials: Record<string, unknown> = {
278→				refresh: tokenData.refresh_token,
279→				access: tokenData.access_token,
280→				expires: expiresAt,
281→			};
282→
283→			// Antigravity requires project discovery after token exchange
284→			if (provider === "google-antigravity") {
285→				credentials.projectId = await discoverAntigravityProject(tokenData.access_token);
286→				console.log(`[oauth] Antigravity project: ${credentials.projectId}`);
287→			}
288→
289→			// Store credentials
290→			await oauthService.storeCredentials(provider as any, credentials as any, { userId });
291→
292→			res.json({
293→				success: true,
294→				data: {
295→					provider,
296→					expiresAt: new Date(expiresAt).toISOString(),
297→				},
298→			});
299→		} catch (err) {
300→			console.error(`[oauth] POST /:provider/callback error:`, err);
301→			res.status(500).json({ success: false, error: "Failed to complete OAuth flow" });
302→		}
303→	});
304→
305→	// -----------------------------------------------------------------------
306→	// GET /:provider/status — Check if user has OAuth credentials for provider
307→	// -----------------------------------------------------------------------
308→	router.get("/:provider/status", async (req: Request, res: Response) => {
309→		try {
310→			const { provider } = req.params;
311→			const userId = req.user!.userId;
312→
313→			const credentials = await oauthService.getCredentials(provider as any, { userId });
314→
315→			if (!credentials) {
316→				res.json({
317→					success: true,
318→					data: {
319→						connected: false,
320→					},
321→				});
322→				return;
323→			}
324→
325→			res.json({
326→				success: true,
327→				data: {
328→					connected: true,
329→					expiresAt: new Date(credentials.expires).toISOString(),
330→					expired: credentials.expires < Date.now(),
331→				},
332→			});
333→		} catch (err) {
334→			console.error(`[oauth] GET /:provider/status error:`, err);
335→			res.status(500).json({ success: false, error: "Failed to check OAuth status" });
336→		}
337→	});
338→
339→	// -----------------------------------------------------------------------
340→	// DELETE /:provider — Disconnect OAuth for provider
341→	// -----------------------------------------------------------------------
342→	router.delete("/:provider", async (req: Request, res: Response) => {
343→		try {
344→			const { provider } = req.params;
345→			const userId = req.user!.userId;
346→
347→			const deleted = await oauthService.deleteCredentials(provider as any, { userId });
348→
349→			if (!deleted) {
350→				res.status(404).json({ success: false, error: "No OAuth credentials found" });
351→				return;
352→			}
353→
354→			res.json({ success: true });
355→		} catch (err) {
356→			console.error(`[oauth] DELETE /:provider error:`, err);
357→			res.status(500).json({ success: false, error: "Failed to disconnect OAuth" });
358→		}
359→	});
360→
361→	// -----------------------------------------------------------------------
362→	// GET / — List all OAuth connections for user
363→	// -----------------------------------------------------------------------
364→	router.get("/", async (req: Request, res: Response) => {
365→		try {
366→			const userId = req.user!.userId;
367→
368→			const credentials = await oauthService.listCredentials({ userId });
369→
370→			res.json({
371→				success: true,
372→				data: {
373→					credentials: credentials.map((cred) => ({
374→						provider: cred.provider,
375→						expiresAt: cred.expiresAt.toISOString(),
376→						expired: cred.expiresAt.getTime() < Date.now(),
377→						createdAt: cred.createdAt.toISOString(),
378→						updatedAt: cred.updatedAt.toISOString(),
379→					})),
380→				},
381→			});
382→		} catch (err) {
383→			console.error("[oauth] GET / error:", err);
384→			res.status(500).json({ success: false, error: "Failed to list OAuth credentials" });
385→		}
386→	});
387→
388→	return router;
389→}
