242→	override connectedCallback() {
243→		super.connectedCallback();
244→		this.loadConnections();
245→
246→		// Listen for postMessage from OAuth callback popup
247→		this.boundMessageHandler = (e: MessageEvent) => this.handleOAuthMessage(e);
