259→	/** Handle postMessage from OAuth callback page */
260→	private handleOAuthMessage(e: MessageEvent) {
261→		if (!e.data || e.data.type !== "oauth-callback") return;
262→		const { code, state } = e.data;
263→		if (!code || !state) return;
264→		// Verify this matches our pending flow
265→		if (state !== this.pendingState) return;
266→
267→		// Auto-complete the flow
268→		this.completeOAuthExchange(code, state);
269→	}
