271→	/** Complete token exchange with the server */
272→	private async completeOAuthExchange(code: string, state: string) {
273→		const provider = this.pendingCodeProvider;
274→		if (!provider) return;
275→
276→		// Close popup if still open
277→		if (this.oauthPopup && !this.oauthPopup.closed) {
278→			this.oauthPopup.close();
279→		}
280→
281→		// Clear pending state
282→		this.pendingCodeProvider = null;
283→		this.pendingState = null;
284→		this.oauthPopup = null;
285→
286→		try {
287→			const callbackResult = await this.fetchApi(`/api/oauth/${provider}/callback`, {
288→				method: "POST",
289→				body: JSON.stringify({ code, state }),
290→			});
291→
292→			if (callbackResult.success) {
293→				this.statusMessage = `Successfully connected ${PROVIDER_LABELS[provider]}`;
294→				this.statusType = "success";
295→				await this.loadConnections();
296→			} else {
297→				this.statusMessage = callbackResult.error || "Failed to complete OAuth flow";
298→				this.statusType = "error";
299→			}
300→		} catch (err) {
301→			console.error("OAuth connection error:", err);
302→			this.statusMessage = "Network error";
303→			this.statusType = "error";
304→		} finally {
305→			this.connecting = { ...this.connecting, [provider]: false };
306→		}
307→	}
