311→	private async loadConnections() {
312→		this.loading = true;
313→		try {
314→			const result = await this.fetchApi("/api/oauth");
315→			if (result.success) {
316→				this.connections = result.data.credentials;
317→			}
318→		} catch (err) {
319→			console.error("Failed to load OAuth connections:", err);
320→		} finally {
321→			this.loading = false;
322→		}
323→	}
