325→	private async handleConnect(provider: string) {
326→		this.connecting = { ...this.connecting, [provider]: true };
327→		this.statusMessage = "";
328→
329→		try {
330→			// Start OAuth flow
331→			const startResult = await this.fetchApi(`/api/oauth/${provider}/start`, {
332→				method: "POST",
333→			});
334→
335→			if (!startResult.success) {
336→				this.statusMessage = startResult.error || "Failed to start OAuth flow";
337→				this.statusType = "error";
338→				this.connecting = { ...this.connecting, [provider]: false };
339→				return;
340→			}
341→
342→			const { authUrl, state } = startResult.data;
343→
344→			// Open OAuth URL in popup
345→			const popup = window.open(
346→				authUrl,
347→				"oauth_popup",
348→				"width=600,height=700,left=100,top=100"
349→			);
350→
351→			if (!popup) {
352→				this.statusMessage = "Please allow popups to connect";
353→				this.statusType = "error";
354→				this.connecting = { ...this.connecting, [provider]: false };
355→				return;
356→			}
357→
358→			// Store state and show inline code input
359→			this.oauthPopup = popup;
360→			this.pendingState = state;
361→			this.pendingCodeProvider = provider;
362→			// connecting state stays true — cleared when code is submitted or cancelled
363→		} catch (err) {
364→			console.error("OAuth connection error:", err);
365→			this.statusMessage = "Network error";
366→			this.statusType = "error";
367→			this.connecting = { ...this.connecting, [provider]: false };
368→		}
369→	}
