371→	private async handleCodeSubmit() {
372→		const provider = this.pendingCodeProvider;
373→		const state = this.pendingState;
374→		if (!provider || !state) return;
375→
376→		const input = this.shadowRoot?.querySelector<HTMLInputElement>("#oauth-code-input");
377→		const rawValue = input?.value?.trim();
378→		if (!rawValue) return;
379→
380→		// Parse input: accept a full redirect URL, "code#state" format, or bare code
381→		let code: string;
382→		try {
383→			const url = new URL(rawValue);
384→			code = url.searchParams.get("code") || rawValue;
385→		} catch {
386→			code = rawValue.split("#")[0];
387→		}
388→
389→		// Close popup if still open
390→		if (this.oauthPopup && !this.oauthPopup.closed) {
391→			this.oauthPopup.close();
392→		}
393→
394→		// Clear the pending state
395→		this.pendingCodeProvider = null;
396→		this.pendingState = null;
397→		this.oauthPopup = null;
398→
399→		try {
400→			const callbackResult = await this.fetchApi(`/api/oauth/${provider}/callback`, {
401→				method: "POST",
402→				body: JSON.stringify({ code, state }),
403→			});
404→
405→			if (callbackResult.success) {
406→				this.statusMessage = `Successfully connected ${PROVIDER_LABELS[provider]}`;
407→				this.statusType = "success";
408→				await this.loadConnections();
409→			} else {
410→				this.statusMessage = callbackResult.error || "Failed to complete OAuth flow";
411→				this.statusType = "error";
412→			}
413→		} catch (err) {
414→			console.error("OAuth connection error:", err);
415→			this.statusMessage = "Network error";
416→			this.statusType = "error";
417→		} finally {
418→			this.connecting = { ...this.connecting, [provider]: false };
419→		}
420→	}
