						<div class="code-input-row">
							<input
								id="oauth-code-input"
								type="text"
								placeholder="Paste code or redirect URL"
								@keydown=${(e: KeyboardEvent) => { if (e.key === "Enter") this.handleCodeSubmit(); }}
							/>
							<button class="btn-primary" @click=${() => this.handleCodeSubmit()}>Submit</button>
